content.content:
1	:root {
2	  --bg: #070B17;
3	  --deep-navy: #0B1121;
4	  --surface: #111A2E;
5	  --surface-elevated: #17233D;
6	  --gold: #FFB800;
7	  --gold-bright: #FFD54A;
8	  --cyan: #22D3EE;
9	  --cyan-bright: #67E8F9;
10	  --blue: #3B82F6;
11	  --blue-bright: #60A5FA;
12	  --violet: #8B5CF6;
13	  --violet-bright: #A78BFA;
14	  --pink: #EC4899;
15	  --pink-bright: #F472B6;
16	  --green: #22C55E;
17	  --green-bright: #4ADE80;
18	  --orange: #F97316;
19	  --orange-bright: #FB923C;
20	  --red: #EF4444;
21	  --red-bright: #F87171;
22	  --text-primary: #FFFFFF;
23	  --text-secondary: #D5DEEB;
24	  --text-muted: #94A3B8;
25	  --accent: var(--gold);
26	}
27	* { margin:0; padding:0; box-sizing:border-box; }
28	html, body { width:100%; height:100%; overflow:hidden; background:var(--bg); font-family:'Inter',sans-serif; color:var(--text-primary); -webkit-font-smoothing:antialiased; }
29	
30	#viewport { position:fixed; inset:0; overflow:hidden; perspective:1200px; background:var(--bg); }
31	
32	#world {
33	  position:absolute;
34	  top:0; left:0;
35	  width:1px; height:1px;
36	  transform-origin:0 0;
37	  will-change:transform;
38	  backface-visibility:hidden;
39	}
40	
41	.parallax-layer {
42	  position:fixed;
43	  inset:0;
44	  pointer-events:none;
45	  z-index:0;
46	  will-change:transform;
47	}
48	
49	/* === SCENE BASE === */
50	.scene {
51	  position:absolute;
52	  transform:translate(-50%,-50%);
53	  z-index:10;
54	  visibility:hidden;
55	  pointer-events:none;
56	}
57	.scene.is-active { visibility:visible; pointer-events:auto; }
58	.scene.is-entering { visibility:visible; pointer-events:none; }
59	.scene.is-leaving { visibility:visible; pointer-events:none; }
60	.scene.is-measuring { visibility:hidden; pointer-events:none; }
61	.scene-inner {
62	  display:flex;
63	  flex-direction:column;
64	  align-items:center;
65	  justify-content:center;
66	  text-align:center;
67	  padding:2.5rem;
68	  min-width:520px;
69	  max-width:920px;
70	}
71	
72	/* === TYPOGRAPHY — STAGE READABLE === */
73	h1, h2, h3 { font-family:'Inter',sans-serif; text-transform:none; letter-spacing:-0.02em; }
74	h1 { font-size:6rem; font-weight:900; }
75	h2 { font-size:4.5rem; font-weight:700; }
76	h3 { font-size:2.5rem; font-weight:600; }
77	p { font-size:1.8rem; font-weight:300; line-height:1.5; color:var(--text-secondary); }
78	
79	/* === TEXT COLOR UTILITIES === */
80	.text-gold { color:var(--gold) !important; }
81	.text-cyan { color:var(--cyan) !important; }
82	.text-violet { color:var(--violet) !important; }
83	.text-blue { color:var(--blue) !important; }
84	.text-pink { color:var(--pink) !important; }
85	.text-green { color:var(--green) !important; }
86	.text-orange { color:var(--orange) !important; }
87	.text-red { color:var(--red) !important; }
88	.text-primary { color:var(--text-primary) !important; }
89	.text-secondary { color:var(--text-secondary) !important; }
90	.text-muted { color:var(--text-muted) !important; }
91	
92	/* === GRADIENT TEXT === */
93	.gradient-gold {
94	  background:linear-gradient(135deg,var(--gold),var(--gold-bright),var(--orange));
95	  -webkit-background-clip:text; background-clip:text; color:transparent;
96	}
97	.gradient-white-gold {
98	  background:linear-gradient(135deg,#FFF,var(--gold));
99	  -webkit-background-clip:text; background-clip:text; color:var(--gold);
100	}
101	.gradient-cyan-violet {
102	  background:linear-gradient(135deg,var(--cyan),var(--violet));
103	  -webkit-background-clip:text; background-clip:text; color:transparent;
104	}
105	.gradient-violet-pink {
106	  background:linear-gradient(135deg,var(--violet),var(--pink));
107	  -webkit-background-clip:text; background-clip:text; color:transparent;
108	}
109	.gradient-red-orange {
110	  background:linear-gradient(135deg,var(--red),var(--orange));
111	  -webkit-background-clip:text; background-clip:text; color:transparent;
112	}
113	
114	/* === SCENE TYPOGRAPHY === */
115	.slide-label {
116	  font-size:1.1rem; font-weight:600; text-transform:uppercase;
117	  letter-spacing:0.15em; color:var(--accent); margin-bottom:1rem;
118	}
119	.s-title { font-size:7rem!important; font-weight:900!important; text-align:center; line-height:1.15; }
120	.s-line { display:inline-block; }
121	.s-question { font-size:4.5rem; font-weight:700; text-align:center; max-width:90%; }
122	.s-question-sm { font-size:2.8rem; font-weight:600; text-align:center; }
123	.s-prompt { font-size:1.8rem; color:var(--text-secondary); margin-bottom:0.8rem; }
124	.s-footnote { font-size:1.15rem; margin-top:0.8rem; color:var(--text-muted); }
125	.s-heading { font-size:3rem; text-align:center; margin-bottom:1.5rem; }
126	.s-statement { font-size:2.5rem; font-weight:300; color:var(--text-secondary); max-width:90%; }
127	.s-bigquestion { font-size:5.5rem; font-weight:900; text-align:center; max-width:90%; line-height:1.2; }
128	.s-strikethrough { font-size:2rem; color:var(--text-muted); text-decoration:line-through; margin-bottom:1.8rem; }
129	.s-faded { font-size:2rem; color:var(--text-secondary); font-weight:300; max-width:80%; }
130	.s-answer { font-size:2.8rem; font-weight:700; margin-top:0.8rem; }
131	.s-sub { font-size:1.6rem; color:var(--text-secondary); }
132	
133	/* === GOLD LINE / DIVIDER === */
134	.gold-line {
135	  width:80px; height:4px;
136	  background:var(--gold); border-radius:2px;
137	  margin:1.5rem 0; position:relative; overflow:hidden;
138	}
139	.gold-line::after {
140	  content:''; position:absolute; top:0; left:-200%;
141	  width:200%; height:100%;
142	  background:linear-gradient(90deg,transparent 0%,#FFD700 30%,#FFB800 50%,#FFD700 70%,transparent 100%);
143	  animation:goldSweep 2.5s ease-in-out infinite;
144	}
145	.gold-line.cyan { background:var(--cyan); }
146	.gold-line.violet { background:var(--violet); }
147	.gold-line.green { background:var(--green); }
148	.gold-line.red { background:var(--red); }
149	.gold-line.orange { background:var(--orange); }
150	.gold-line.cyan::after,
151	.gold-line.violet::after,
152	.gold-line.green::after,
153	.gold-line.red::after,
154	.gold-line.orange::after { background:none; }
155	@keyframes goldSweep { 0%{left:-200%}100%{left:200%} }
156	
157	/* === CARD VARIANTS === */
158	.card-base {
159	  background:linear-gradient(145deg,rgba(23,35,61,0.96),rgba(11,17,33,0.96));
160	  border-radius:16px; padding:2.5rem; position:relative;
161	  max-width:90%;
162	}
163	.card-gold {
164	  border:1px solid rgba(255,184,0,0.35);
165	  box-shadow:0 20px 60px rgba(0,0,0,0.35), 0 0 40px rgba(255,184,0,0.10);
166	}
167	.card-cyan {
168	  border:1px solid rgba(34,211,238,0.35);
169	  box-shadow:0 20px 60px rgba(0,0,0,0.35), 0 0 40px rgba(34,211,238,0.10);
170	}
171	.card-violet {
172	  border:1px solid rgba(139,92,246,0.35);
173	  box-shadow:0 20px 60px rgba(0,0,0,0.35), 0 0 40px rgba(139,92,246,0.10);
174	}
175	.card-green {
176	  border:1px solid rgba(34,197,94,0.35);
177	  box-shadow:0 20px 60px rgba(0,0,0,0.35), 0 0 40px rgba(34,197,94,0.10);
178	}
179	.card-red {
180	  border:1px solid rgba(239,68,68,0.35);
181	  box-shadow:0 20px 60px rgba(0,0,0,0.35), 0 0 40px rgba(239,68,68,0.10);
182	}
183	.card-orange {
184	  border:1px solid rgba(249,115,22,0.35);
185	  box-shadow:0 20px 60px rgba(0,0,0,0.35), 0 0 40px rgba(249,115,22,0.10);
186	}
187	
188	/* === QUOTE CARD (legacy — now uses card-base + variant) === */
189	.quote-card {
190	  background:linear-gradient(145deg,rgba(23,35,61,0.96),rgba(11,17,33,0.96));
191	  border-left:6px solid var(--gold);
192	  border-radius:16px;
193	  padding:2.5rem;
194	  max-width:90%;
195	  box-shadow:0 20px 60px rgba(0,0,0,0.35), 0 0 35px rgba(255,184,0,0.10);
196	}
197	.quote-card .q-sub { font-size:2rem; font-weight:300; color:var(--text-secondary); margin-bottom:0.5rem; }
198	.quote-card .q-main { font-size:3rem; font-weight:700; color:var(--text-primary); line-height:1.3; }
199	.quote-card .q-attribution { font-size:1.3rem; color:var(--text-muted); margin-top:1rem; font-weight:300; }
200	.quote-card.card-cyan { border-left-color:var(--cyan); }
201	.quote-card.card-violet { border-left-color:var(--violet); }
202	.quote-card.card-red { border-left-color:var(--red); }
203	.quote-card.card-orange { border-left-color:var(--orange); }
204	.quote-card.card-green { border-left-color:var(--green); }
205	
206	/* === BIG NUMBER === */
207	.big-number { font-size:9rem; font-weight:900; color:var(--gold); line-height:1; letter-spacing:-0.04em; }
208	.big-number-sm { font-size:6rem; font-weight:900; color:var(--gold); line-height:1; }
209	
210	/* === LIMITS GRID === */
211	.limits-grid { display:flex; gap:2.5rem; margin-top:1.5rem; }
212	.limit-item { display:flex; flex-direction:column; align-items:center; gap:1rem; }
213	.limit-visual { width:180px; height:180px; border-radius:24px; overflow:hidden; position:relative; isolation:isolate; background:rgba(255,255,255,0.04); }
214	.limit-visual img { width:100%; height:100%; display:block; object-fit:cover; }
215	.limit-image-overlay { position:absolute; inset:0; pointer-events:none; background:linear-gradient(180deg,rgba(7,11,23,0.02),rgba(7,11,23,0.68)); }
216	.limit-visual.is-limited::after { content:''; position:absolute; inset:0; pointer-events:none; background:linear-gradient(135deg,transparent 48%,rgba(239,68,68,0.35) 49%,rgba(239,68,68,0.35) 51%,transparent 52%); }
217	.limit-visual.is-open { box-shadow:inset 0 0 30px rgba(34,211,238,0.08); }
218	.limit-visual.image-failed { background:rgba(255,255,255,0.04); box-shadow:inset 0 0 20px rgba(255,255,255,0.06); }
219	.limit-visual.image-failed img { display:none; }
220	.limit-label { font-size:1.8rem; font-weight:700; color:var(--text-muted); }
221	.limit-sub { font-size:1.15rem; color:var(--text-secondary); }
222	
223	/* === BOTTLENECK === */
224	.bottleneck-visual { display:flex; flex-direction:column; align-items:center; gap:1rem; }
225	.b-old { font-size:3.5rem; font-weight:700; color:var(--text-muted); text-decoration:line-through; opacity:0.5; }
226	.b-arrow { font-size:2.2rem; color:var(--gold); animation:bounceArrow 1.5s ease-in-out infinite; }
227	@keyframes bounceArrow { 0%,100%{transform:translateY(0)}50%{transform:translateY(8px);opacity:0.6} }
228	.b-now { font-size:1.4rem; color:var(--gold); font-weight:600; }
229	.b-items { display:flex; gap:1.5rem; }
230	.b-items span { font-size:3rem; font-weight:800; padding:0.8rem 1.8rem; background:var(--surface); border-radius:12px; }
231	.b-items .b-ask { color:var(--cyan); border-left:5px solid var(--cyan); box-shadow:0 0 30px rgba(34,211,238,0.08); }
232	.b-items .b-judge { color:var(--violet); border-left:5px solid var(--violet); box-shadow:0 0 30px rgba(139,92,246,0.08); }
233	.b-items .b-act { color:var(--green); border-left:5px solid var(--green); box-shadow:0 0 30px rgba(34,197,94,0.08); }
234	
235	/* === SPLIT VIEW === */
236	.split-view { display:flex; gap:0; border-radius:16px; overflow:hidden; }
237	.split-side { flex:1; padding:2.5rem 2rem; display:flex; flex-direction:column; align-items:center; gap:1rem; min-width:320px; }
238	.split-worried { background:rgba(239,68,68,0.1); border-right:1px solid rgba(255,255,255,0.06); }
239	.split-over { background:rgba(34,197,94,0.08); }
240	.split-label { font-size:1.1rem; font-weight:700; text-transform:uppercase; letter-spacing:0.15em; }
241	.split-worried .split-label { color:var(--red); }
242	.split-over .split-label { color:var(--green); }
243	.split-person-visual { width:300px; height:240px; border-radius:28px; overflow:hidden; position:relative; isolation:isolate; background:rgba(255,255,255,0.04); flex-shrink:0; }
244	.split-person-visual img { width:100%; height:100%; display:block; object-fit:cover; }
245	.split-person-overlay { position:absolute; inset:0; pointer-events:none; background:linear-gradient(180deg,rgba(7,11,23,0.02),rgba(7,11,23,0.55)); }
246	.split-person-visual.image-failed { background:rgba(255,255,255,0.04); }
247	.split-person-visual.image-failed img { display:none; }
248	.split-thought { font-size:1.5rem; color:var(--text-secondary); font-style:italic; max-width:260px; }
249	.split-tag { font-size:0.9rem; font-weight:600; opacity:0.7; }
250	
251	/* === PROMPT CARDS === */
252	.prompt-card { background:linear-gradient(145deg,rgba(23,35,61,0.96),rgba(11,17,33,0.96)); border-radius:14px; padding:2rem; min-width:520px; max-width:700px; }
253	.prompt-generic { border:1px solid rgba(148,163,184,0.2); }
254	.prompt-contextual { border:1px solid rgba(34,211,238,0.4); box-shadow:0 0 30px rgba(34,211,238,0.08); }
255	.prompt-label { font-size:0.85rem; font-weight:700; text-transform:uppercase; letter-spacing:0.12em; margin-bottom:1rem; }
256	.prompt-label.generic { color:var(--text-muted); }
257	.prompt-label.contextual { color:var(--cyan); }
258	.prompt-text { font-size:1.4rem; color:var(--text-secondary); font-weight:300; line-height:1.6; font-style:italic; }
259	.prompt-result { font-size:1.15rem; margin-top:1rem; padding:0.8rem 1rem; border-radius:8px; }
260	.prompt-generic .prompt-result { background:rgba(255,255,255,0.03); }
261	.prompt-contextual .prompt-result { background:rgba(34,211,238,0.06); border-left:3px solid var(--cyan); }
262	
263	/* === TOOL CONSTELLATION === */
264	.constellation { position:relative; width:1400px; height:950px; margin:0 auto; }
265	#scene-ai-ecosystem .constellation { margin:0; }
266	#scene-ai-ecosystem .constellation-center {
267	  position:absolute; left:50%; top:50%; transform:translate(-50%,-50%);
268	  z-index:3; display:flex; flex-direction:column; align-items:center; justify-content:center;
269	  width:min(760px,70%); text-align:center; pointer-events:none;
270	}
271	#scene-ai-ecosystem .constellation-center .slide-label { margin-bottom:1rem; }
272	#scene-ai-ecosystem .constellation-center .s-heading { margin:0; max-width:760px; line-height:1.15; }
273	#scene-ai-ecosystem .constellation-origin { position:absolute; left:50%; top:50%; width:0; height:0; z-index:2; }
274	#scene-ai-ecosystem #connections-canvas { z-index:0; }
275	#connections-canvas { position:absolute; inset:0; width:100%; height:100%; pointer-events:none; z-index:0; }
276	.tool-node {
277	  position:absolute; display:flex; flex-direction:column; align-items:center; gap:0.6rem;
278	  cursor:pointer; z-index:2; opacity:0;
279	  transform:translate(-50%,-50%);
280	}
281	.tool-node .tn-icon { width:80px; height:80px; border-radius:16px; display:flex; align-items:center; justify-content:center; border:1px solid rgba(255,255,255,0.12); background:rgba(17,26,46,0.9); }
282	.tool-node .tn-name { font-size:1.5rem; font-weight:700; color:var(--text-primary); white-space:nowrap; }
283	.tool-node .tn-cap { font-size:1.15rem; font-weight:500; color:var(--text-secondary); white-space:nowrap; }
284	.tool-node .tn-icon svg { width:40px; height:40px; }
285	.tool-node:hover .tn-icon { border-color:var(--gold); box-shadow:0 0 25px rgba(255,184,0,0.15); }
286	
287	/* === 10/10 DISPLAY === */
288	.ten-display { display:flex; align-items:baseline; gap:0.8rem; margin:0.5rem 0; }
289	.ten-number { font-size:7rem; font-weight:900; color:var(--gold); line-height:1; }
290	.ten-label { font-size:1.8rem; color:var(--text-muted); font-weight:300; }
291	
292	/* === SPOTLIGHT CARDS === */
293	.spotlight-card { background:linear-gradient(145deg,rgba(23,35,61,0.96),rgba(11,17,33,0.96)); border-radius:16px; padding:2.5rem; text-align:center; min-width:600px; border:1px solid rgba(255,255,255,0.08); }
294	.spotlight-card .sp-tag { font-size:0.9rem; font-weight:600; text-transform:uppercase; letter-spacing:0.1em; padding:0.4rem 1rem; border-radius:100px; display:inline-block; margin-bottom:1rem; }
295	.spotlight-card h3 { font-size:2.5rem; font-weight:700; margin-bottom:0.8rem; }
296	.spotlight-card p { font-size:1.5rem; color:var(--text-secondary); font-weight:300; line-height:1.5; }
297	.sp-design .sp-tag { color:var(--violet); background:rgba(139,92,246,0.12); }
298	.sp-code .sp-tag { color:var(--cyan); background:rgba(34,211,238,0.12); }
299	.sp-multi .sp-tag { color:var(--gold); background:rgba(255,184,0,0.12); }
300	
301	/* === CHALLENGE TRIANGLE === */
302	.challenge-triangle { display:grid; grid-template-columns:1fr 1fr; gap:2rem; align-items:center; }
303	.ct-item { text-align:center; padding:1.2rem 2rem; border-radius:14px; background:linear-gradient(145deg,rgba(23,35,61,0.96),rgba(11,17,33,0.96)); }
304	.ct-item p { font-size:1.15rem; color:var(--text-muted); margin-top:0.3rem; }
305	.ct-top { grid-column:1/-1; }
306	.ct-gold { border:1px solid rgba(255,184,0,0.35); box-shadow:0 0 20px rgba(255,184,0,0.08); }
307	.ct-cyan { border:1px solid rgba(34,211,238,0.35); box-shadow:0 0 20px rgba(34,211,238,0.08); }
308	.ct-green { border:1px solid rgba(34,197,94,0.35); box-shadow:0 0 20px rgba(34,197,94,0.08); }
309	.ct-gold .big-number-sm { color:var(--gold); }
310	.ct-cyan .big-number-sm { color:var(--cyan); }
311	.ct-green .big-number-sm { color:var(--green); }
312	
313	/* === NOUN LIST === */
314	.nouns-list { display:flex; flex-direction:column; gap:0.5rem; }
315	.nouns-list span { font-size:2.8rem; font-weight:300; color:#64758B; }
316	
317	/* === QUESTION LIST === */
318	.questions-list { display:flex; flex-direction:column; gap:0.8rem; }
319	.questions-list span { font-size:1.8rem; font-weight:400; padding:0.3rem 0; line-height:1.4; }
320	
321	/* === EQUATION DISPLAY (DANGER) === */
322	.equation-display { display:flex; align-items:center; gap:1rem; justify-content:center; }
323	.eq-part { font-size:9rem; font-weight:900; letter-spacing:-0.04em; line-height:1; }
324	.eq-one { color:var(--text-primary); }
325	.eq-op { font-size:5rem; color:var(--red); opacity:0.5; }
326	.eq-tenk { color:var(--red); text-shadow:0 0 40px rgba(239,68,68,0.3); }
327	.eq-caption { font-size:1.6rem; color:var(--text-muted); font-weight:300; margin-top:1rem; }
328	.danger-grid { display:flex; flex-wrap:wrap; gap:1.2rem; justify-content:center; margin-top:1.5rem; width:100%; }
329	.d-node { display:flex; align-items:center; gap:0.8rem; padding:0.8rem 1.5rem; border-radius:10px; font-size:1.4rem; color:var(--text-secondary); background:linear-gradient(145deg,rgba(23,35,61,0.96),rgba(11,17,33,0.96)); }
330	.d-node .d-icon { display:inline-flex; align-items:center; justify-content:center; width:24px; height:24px; }
331	.d-node .d-icon svg { width:18px; height:18px; }
332	.d-node.d-hallucination { border:1px solid rgba(239,68,68,0.35); }
333	.d-node.d-security { border:1px solid rgba(249,115,22,0.35); }
334	.d-node.d-scaling { border:1px solid rgba(239,68,68,0.35); }
335	.d-node.d-confidence { border:1px solid rgba(249,115,22,0.35); }
336	
337	/* === UPDATE STACK === */
338	.update-stack { display:flex; flex-direction:column; gap:1rem; }
339	.update-item { font-size:3rem; font-weight:500; color:var(--text-secondary); line-height:1.4; }
340	
341	/* === FINAL QUESTION === */
342	.final-question { font-size:7.5rem; font-weight:900; color:var(--text-primary); text-align:center; line-height:1.15; max-width:90%; }
343	
344	/* === FINAL BLOCK === */
345	.final-block p { font-size:2rem; color:var(--text-secondary); font-weight:300; line-height:1.5; max-width:85%; margin:0 auto 1.2rem; }
346	.final-block .fq { font-size:2.8rem; }
347	.final-block .fq-main { font-size:4.5rem; font-weight:700; }
348	
349	/* === THANK YOU === */
350	.thank-you-text { font-size:6rem; font-weight:700; color:var(--gold); text-align:center; text-shadow:0 0 30px rgba(255,184,0,0.15); }
351	
352	/* === AMBIENT GLOWS === */
353	.ambient-glow {
354	  position:absolute;
355	  pointer-events:none;
356	  z-index:1;
357	  border-radius:50%;
358	  transform:translate(-50%,-50%);
359	  filter:blur(120px);
360	}
361	.glow-gold   { width:2400px; height:2400px; background:radial-gradient(ellipse,rgba(255,184,0,0.10),transparent 60%); }
362	.glow-cyan   { width:2200px; height:2200px; background:radial-gradient(ellipse,rgba(34,211,238,0.08),transparent 60%); }
363	.glow-violet { width:2200px; height:2200px; background:radial-gradient(ellipse,rgba(139,92,246,0.08),transparent 60%); }
364	.glow-blue   { width:2400px; height:2400px; background:radial-gradient(ellipse,rgba(59,130,246,0.08),transparent 60%); }
365	.glow-green  { width:2000px; height:2000px; background:radial-gradient(ellipse,rgba(34,197,94,0.07),transparent 60%); }
366	.glow-red    { width:2200px; height:2200px; background:radial-gradient(ellipse,rgba(239,68,68,0.08),transparent 60%); }
367	.glow-orange { width:2200px; height:2200px; background:radial-gradient(ellipse,rgba(249,115,22,0.08),transparent 60%); }
368	
369	/* === PARALLAX === */
370	#parallax-back {
371	  background:radial-gradient(ellipse 60% 50% at 20% 30%,rgba(7,11,23,0.7),transparent),radial-gradient(ellipse 40% 40% at 80% 70%,rgba(17,26,46,0.3),transparent);
372	  opacity:0.7;
373	}
374	#parallax-mid {
375	  background:radial-gradient(ellipse 50% 30% at 50% 20%,rgba(255,184,0,0.02),transparent),radial-gradient(ellipse 30% 40% at 70% 80%,rgba(34,211,238,0.02),transparent);
376	  opacity:0.4;
377	}
378	
379	/* === HUD === */
380	#hud {
381	  position:fixed; bottom:2rem; left:50%; transform:translateX(-50%);
382	  display:flex; align-items:center; gap:1rem;
383	  z-index:1000;
384	  opacity:1;
385	  transition:opacity 0.5s ease;
386	}
387	#hud.hud-hidden { opacity:0.15; }
388	#hud.hud-hidden:hover { opacity:1; }
389	.hud-btn {
390	  background:rgba(17,26,46,0.85); border:1px solid rgba(255,255,255,0.08);
391	  color:var(--gold); font-size:1.2rem;
392	  width:40px; height:40px; border-radius:50%;
393	  cursor:pointer; display:flex; align-items:center; justify-content:center;
394	  transition:background 0.2s; font-family:inherit;
395	}
396	.hud-btn:hover { background:rgba(255,184,0,0.12); }
397	.hud-btn-sm { width:32px; height:32px; font-size:0.9rem; }
398	#progress-bar { width:120px; height:2px; background:rgba(255,255,255,0.06); border-radius:2px; overflow:hidden; }
399	#progress-fill { height:100%; width:0%; background:var(--gold); transition:width 0.4s ease; }
400	
401	/* === ZONE LABELS === */
402	#zone-labels {
403	  position:fixed; inset:0;
404	  display:flex; flex-wrap:wrap; align-items:center; justify-content:center;
405	  gap:3rem;
406	  pointer-events:none;
407	  z-index:500;
408	  opacity:0;
409	  transition:opacity 0.6s ease;
410	}
411	#zone-labels.active { opacity:1; pointer-events:auto; }
412	.zl-item {
413	  font-size:1.4rem; font-weight:700; color:var(--text-muted);
414	  text-transform:uppercase; letter-spacing:0.08em;
415	  cursor:pointer; padding:0.5rem 1.5rem; border:1px solid rgba(255,255,255,0.06);
416	  border-radius:8px; transition:all 0.3s; background:rgba(7,11,23,0.85);
417	}
418	.zl-item:hover { color:var(--gold); border-color:var(--gold); background:rgba(255,184,0,0.06); }
419	
420	/* === PARTICLES === */
421	#particle-canvas { position:fixed; inset:0; width:100%; height:100%; pointer-events:none; z-index:999; opacity:0; transition:opacity 0.8s ease; }
422	#particle-canvas.active { opacity:1; }
423	
424	/* === KEYFRAMES === */
425	@keyframes elasticBounce {
426	  0%{transform:scale(0.2);opacity:0}
427	  50%{transform:scale(1.12)}
428	  70%{transform:scale(0.9)}
429	  85%{transform:scale(1.05)}
430	  100%{transform:scale(1);opacity:1}
431	}
432	.elastic-bounce { animation:elasticBounce 1.2s cubic-bezier(0.68,-0.55,0.27,1.55) forwards; }
433	@keyframes fadeUp { from{opacity:0;transform:translateY(20px)} to{opacity:1;transform:translateY(0)} }
434	.fade-up { animation:fadeUp 0.7s ease forwards; }
435	@keyframes slideInLeft { from{transform:translateX(-100%);opacity:0} to{transform:translateX(0);opacity:1} }
436	@keyframes slideInRight { from{transform:translateX(-100%);opacity:0} to{transform:translateX(0);opacity:1} }
437	@keyframes pulseGlow {
438	  0%,100%{text-shadow:0 0 20px rgba(255,184,0,0.3),0 0 40px rgba(255,184,0,0.1)}
439	  50%{text-shadow:0 0 40px rgba(255,184,0,0.5),0 0 80px rgba(255,184,0,0.2)}
440	}
441	.word-fade span { display:inline-block; opacity:0; transition:opacity 0.4s ease; }
442	
443	/* === RESPONSIVE === */
444	@media (max-width:1024px) {
445	  .scene-inner { min-width:380px; max-width:600px; padding:1.5rem; }
446	  h1,.s-title { font-size:4rem!important; }
447	  .s-question { font-size:2.8rem; }
448	  .s-bigquestion { font-size:3rem; }
449	  .big-number { font-size:5rem; }
450	  .big-number-sm { font-size:3.5rem; }
451	  .s-heading { font-size:2.2rem; }
452	  .s-statement { font-size:1.8rem; }
453	  .s-question-sm { font-size:2rem; }
454	  .final-question { font-size:4.5rem; }
455	  .final-block .fq-main { font-size:3rem; }
456	  .thank-you-text { font-size:4rem; }
457	  .quote-card .q-main { font-size:2.2rem; }
458	  .limits-grid { flex-wrap:wrap; justify-content:center; }
459	  .limits-grid .limit-item { flex-basis:40%; }
460	  .b-items { flex-direction:column; align-items:center; }
461	  .b-items span { font-size:2rem; }
462	  .constellation { width:700px; height:600px; }
463	  .tool-node .tn-icon { width:56px; height:56px; }
464	  .tool-node .tn-icon svg { width:28px; height:28px; }
465	  .tool-node .tn-name { font-size:1.1rem; }
466	  .tool-node .tn-cap { font-size:0.85rem; }
467	  .ten-number { font-size:4.5rem; }
468	  .eq-part { font-size:5rem; }
469	  .split-view { flex-direction:column; }
470	  .split-side { min-width:auto; }
471	  .nouns-list span { font-size:2rem; }
472	  .questions-list span { font-size:1.3rem; }
473	  .prompt-card { min-width:360px; max-width:500px; }
474	  .spotlight-card { min-width:400px; }
475	  .d-node { font-size:1.1rem; }
476	  .update-item { font-size:2rem; }
477	  .eq-part { font-size:6rem; }
478	}
479	@media (max-width:768px) {
480	  .scene-inner { min-width:260px; max-width:420px; padding:1.2rem; }
481	  h1,.s-title { font-size:2.8rem!important; }
482	  .s-question { font-size:2rem; }
483	  .s-bigquestion { font-size:2.2rem; }
484	  .big-number { font-size:3.5rem; }
485	  .constellation { width:360px; height:380px; }
486	  .tool-node .tn-icon { width:40px; height:40px; }
487	  .tool-node .tn-icon svg { width:20px; height:20px; }
488	  .tool-node .tn-name { font-size:0.8rem; }
489	  .tool-node .tn-cap { display:none; }
490	  .update-item { font-size:1.6rem; }
491	  .final-question { font-size:3rem; }
492	  .final-block .fq-main { font-size:2.2rem; }
493	  .thank-you-text { font-size:3rem; }
494	  .ten-number { font-size:3rem; }
495	  .eq-part { font-size:3.5rem; }
496	  .prompt-card { min-width:220px; max-width:360px; }
497	  .spotlight-card { min-width:240px; }
498	  #hud { bottom:1rem; gap:0.6rem; }
499	  #progress-bar { width:60px; }
500	  .zl-item { font-size:0.9rem; padding:0.3rem 1rem; }
501	  .d-node { font-size:0.9rem; }
502	  .limit-visual { width:120px; height:120px; }
503	}
504	@media (prefers-reduced-motion:reduce) {
505	  *,*::before,*::after { animation-duration:0.01ms!important; transition-duration:0.01ms!important; }
506	  .gold-line::after { animation:none; background:var(--gold); }
507	  .b-arrow { animation:none; }
508	}
509

file.content:
:root {
  --bg: #070B17;
  --deep-navy: #0B1121;
  --surface: #111A2E;
  --surface-elevated: #17233D;
  --gold: #FFB800;
  --gold-bright: #FFD54A;
  --cyan: #22D3EE;
  --cyan-bright: #67E8F9;
  --blue: #3B82F6;
  --blue-bright: #60A5FA;
  --violet: #8B5CF6;
  --violet-bright: #A78BFA;
  --pink: #EC4899;
  --pink-bright: #F472B6;
  --green: #22C55E;
  --green-bright: #4ADE80;
  --orange: #F97316;
  --orange-bright: #FB923C;
  --red: #EF4444;
  --red-bright: #F87171;
  --text-primary: #FFFFFF;
  --text-secondary: #D5DEEB;
  --text-muted: #94A3B8;
  --accent: var(--gold);
}
* { margin:0; padding:0; box-sizing:border-box; }
html, body { width:100%; height:100%; overflow:hidden; background:var(--bg); font-family:'Inter',sans-serif; color:var(--text-primary); -webkit-font-smoothing:antialiased; }

#viewport { position:fixed; inset:0; overflow:hidden; perspective:1200px; background:var(--bg); }

#world {
  position:absolute;
  top:0; left:0;
  width:1px; height:1px;
  transform-origin:0 0;
  will-change:transform;
  backface-visibility:hidden;
}

.parallax-layer {
  position:fixed;
  inset:0;
  pointer-events:none;
  z-index:0;
  will-change:transform;
}

/* === SCENE BASE === */
.scene {
  position:absolute;
  transform:translate(-50%,-50%);
  z-index:10;
  visibility:hidden;
  pointer-events:none;
}
.scene.is-active { visibility:visible; pointer-events:auto; }
.scene.is-entering { visibility:visible; pointer-events:none; }
.scene.is-leaving { visibility:visible; pointer-events:none; }
.scene.is-measuring { visibility:hidden; pointer-events:none; }
.scene-inner {
  display:flex;
  flex-direction:column;
  align-items:center;
  justify-content:center;
  text-align:center;
  padding:2.5rem;
  min-width:520px;
  max-width:920px;
}

/* === TYPOGRAPHY — STAGE READABLE === */
h1, h2, h3 { font-family:'Inter',sans-serif; text-transform:none; letter-spacing:-0.02em; }
h1 { font-size:6rem; font-weight:900; }
h2 { font-size:4.5rem; font-weight:700; }
h3 { font-size:2.5rem; font-weight:600; }
p { font-size:1.8rem; font-weight:300; line-height:1.5; color:var(--text-secondary); }

/* === TEXT COLOR UTILITIES === */
.text-gold { color:var(--gold) !important; }
.text-cyan { color:var(--cyan) !important; }
.text-violet { color:var(--violet) !important; }
.text-blue { color:var(--blue) !important; }
.text-pink { color:var(--pink) !important; }
.text-green { color:var(--green) !important; }
.text-orange { color:var(--orange) !important; }
.text-red { color:var(--red) !important; }
.text-primary { color:var(--text-primary) !important; }
.text-secondary { color:var(--text-secondary) !important; }
.text-muted { color:var(--text-muted) !important; }

/* === GRADIENT TEXT === */
.gradient-gold {
  background:linear-gradient(135deg,var(--gold),var(--gold-bright),var(--orange));
  -webkit-background-clip:text; background-clip:text; color:transparent;
}
.gradient-white-gold {
  background:linear-gradient(135deg,#FFF,var(--gold));
  -webkit-background-clip:text; background-clip:text; color:var(--gold);
}
.gradient-cyan-violet {
  background:linear-gradient(135deg,var(--cyan),var(--violet));
  -webkit-background-clip:text; background-clip:text; color:transparent;
}
.gradient-violet-pink {
  background:linear-gradient(135deg,var(--violet),var(--pink));
  -webkit-background-clip:text; background-clip:text; color:transparent;
}
.gradient-red-orange {
  background:linear-gradient(135deg,var(--red),var(--orange));
  -webkit-background-clip:text; background-clip:text; color:transparent;
}

/* === SCENE TYPOGRAPHY === */
.slide-label {
  font-size:1.1rem; font-weight:600; text-transform:uppercase;
  letter-spacing:0.15em; color:var(--accent); margin-bottom:1rem;
}
.s-title { font-size:7rem!important; font-weight:900!important; text-align:center; line-height:1.15; }
.s-line { display:inline-block; }
.s-question { font-size:4.5rem; font-weight:700; text-align:center; max-width:90%; }
.s-question-sm { font-size:2.8rem; font-weight:600; text-align:center; }
.s-prompt { font-size:1.8rem; color:var(--text-secondary); margin-bottom:0.8rem; }
.s-footnote { font-size:1.15rem; margin-top:0.8rem; color:var(--text-muted); }
.s-heading { font-size:3rem; text-align:center; margin-bottom:1.5rem; }
.s-statement { font-size:2.5rem; font-weight:300; color:var(--text-secondary); max-width:90%; }
.s-bigquestion { font-size:5.5rem; font-weight:900; text-align:center; max-width:90%; line-height:1.2; }
.s-strikethrough { font-size:2rem; color:var(--text-muted); text-decoration:line-through; margin-bottom:1.8rem; }
.s-faded { font-size:2rem; color:var(--text-secondary); font-weight:300; max-width:80%; }
.s-answer { font-size:2.8rem; font-weight:700; margin-top:0.8rem; }
.s-sub { font-size:1.6rem; color:var(--text-secondary); }

/* === GOLD LINE / DIVIDER === */
.gold-line {
  width:80px; height:4px;
  background:var(--gold); border-radius:2px;
  margin:1.5rem 0; position:relative; overflow:hidden;
}
.gold-line::after {
  content:''; position:absolute; top:0; left:-200%;
  width:200%; height:100%;
  background:linear-gradient(90deg,transparent 0%,#FFD700 30%,#FFB800 50%,#FFD700 70%,transparent 100%);
  animation:goldSweep 2.5s ease-in-out infinite;
}
.gold-line.cyan { background:var(--cyan); }
.gold-line.violet { background:var(--violet); }
.gold-line.green { background:var(--green); }
.gold-line.red { background:var(--red); }
.gold-line.orange { background:var(--orange); }
.gold-line.cyan::after,
.gold-line.violet::after,
.gold-line.green::after,
.gold-line.red::after,
.gold-line.orange::after { background:none; }
@keyframes goldSweep { 0%{left:-200%}100%{left:200%} }

/* === CARD VARIANTS === */
.card-base {
  background:linear-gradient(145deg,rgba(23,35,61,0.96),rgba(11,17,33,0.96));
  border-radius:16px; padding:2.5rem; position:relative;
  max-width:90%;
}
.card-gold {
  border:1px solid rgba(255,184,0,0.35);
  box-shadow:0 20px 60px rgba(0,0,0,0.35), 0 0 40px rgba(255,184,0,0.10);
}
.card-cyan {
  border:1px solid rgba(34,211,238,0.35);
  box-shadow:0 20px 60px rgba(0,0,0,0.35), 0 0 40px rgba(34,211,238,0.10);
}
.card-violet {
  border:1px solid rgba(139,92,246,0.35);
  box-shadow:0 20px 60px rgba(0,0,0,0.35), 0 0 40px rgba(139,92,246,0.10);
}
.card-green {
  border:1px solid rgba(34,197,94,0.35);
  box-shadow:0 20px 60px rgba(0,0,0,0.35), 0 0 40px rgba(34,197,94,0.10);
}
.card-red {
  border:1px solid rgba(239,68,68,0.35);
  box-shadow:0 20px 60px rgba(0,0,0,0.35), 0 0 40px rgba(239,68,68,0.10);
}
.card-orange {
  border:1px solid rgba(249,115,22,0.35);
  box-shadow:0 20px 60px rgba(0,0,0,0.35), 0 0 40px rgba(249,115,22,0.10);
}

/* === QUOTE CARD (legacy — now uses card-base + variant) === */
.quote-card {
  background:linear-gradient(145deg,rgba(23,35,61,0.96),rgba(11,17,33,0.96));
  border-left:6px solid var(--gold);
  border-radius:16px;
  padding:2.5rem;
  max-width:90%;
  box-shadow:0 20px 60px rgba(0,0,0,0.35), 0 0 35px rgba(255,184,0,0.10);
}
.quote-card .q-sub { font-size:2rem; font-weight:300; color:var(--text-secondary); margin-bottom:0.5rem; }
.quote-card .q-main { font-size:3rem; font-weight:700; color:var(--text-primary); line-height:1.3; }
.quote-card .q-attribution { font-size:1.3rem; color:var(--text-muted); margin-top:1rem; font-weight:300; }
.quote-card.card-cyan { border-left-color:var(--cyan); }
.quote-card.card-violet { border-left-color:var(--violet); }
.quote-card.card-red { border-left-color:var(--red); }
.quote-card.card-orange { border-left-color:var(--orange); }
.quote-card.card-green { border-left-color:var(--green); }

/* === BIG NUMBER === */
.big-number { font-size:9rem; font-weight:900; color:var(--gold); line-height:1; letter-spacing:-0.04em; }
.big-number-sm { font-size:6rem; font-weight:900; color:var(--gold); line-height:1; }

/* === LIMITS GRID === */
.limits-grid { display:flex; gap:2.5rem; margin-top:1.5rem; }
.limit-item { display:flex; flex-direction:column; align-items:center; gap:1rem; }
.limit-visual { width:180px; height:180px; border-radius:24px; overflow:hidden; position:relative; isolation:isolate; background:rgba(255,255,255,0.04); }
.limit-visual img { width:100%; height:100%; display:block; object-fit:cover; }
.limit-image-overlay { position:absolute; inset:0; pointer-events:none; background:linear-gradient(180deg,rgba(7,11,23,0.02),rgba(7,11,23,0.68)); }
.limit-visual.is-limited::after { content:''; position:absolute; inset:0; pointer-events:none; background:linear-gradient(135deg,transparent 48%,rgba(239,68,68,0.35) 49%,rgba(239,68,68,0.35) 51%,transparent 52%); }
.limit-visual.is-open { box-shadow:inset 0 0 30px rgba(34,211,238,0.08); }
.limit-visual.image-failed { background:rgba(255,255,255,0.04); box-shadow:inset 0 0 20px rgba(255,255,255,0.06); }
.limit-visual.image-failed img { display:none; }
.limit-label { font-size:1.8rem; font-weight:700; color:var(--text-muted); }
.limit-sub { font-size:1.15rem; color:var(--text-secondary); }

/* === BOTTLENECK === */
.bottleneck-visual { display:flex; flex-direction:column; align-items:center; gap:1rem; }
.b-old { font-size:3.5rem; font-weight:700; color:var(--text-muted); text-decoration:line-through; opacity:0.5; }
.b-arrow { font-size:2.2rem; color:var(--gold); animation:bounceArrow 1.5s ease-in-out infinite; }
@keyframes bounceArrow { 0%,100%{transform:translateY(0)}50%{transform:translateY(8px);opacity:0.6} }
.b-now { font-size:1.4rem; color:var(--gold); font-weight:600; }
.b-items { display:flex; gap:1.5rem; }
.b-items span { font-size:3rem; font-weight:800; padding:0.8rem 1.8rem; background:var(--surface); border-radius:12px; }
.b-items .b-ask { color:var(--cyan); border-left:5px solid var(--cyan); box-shadow:0 0 30px rgba(34,211,238,0.08); }
.b-items .b-judge { color:var(--violet); border-left:5px solid var(--violet); box-shadow:0 0 30px rgba(139,92,246,0.08); }
.b-items .b-act { color:var(--green); border-left:5px solid var(--green); box-shadow:0 0 30px rgba(34,197,94,0.08); }

/* === SPLIT VIEW === */
.split-view { display:flex; gap:0; border-radius:16px; overflow:hidden; }
.split-side { flex:1; padding:2.5rem 2rem; display:flex; flex-direction:column; align-items:center; gap:1rem; min-width:320px; }
.split-worried { background:rgba(239,68,68,0.1); border-right:1px solid rgba(255,255,255,0.06); }
.split-over { background:rgba(34,197,94,0.08); }
.split-label { font-size:1.1rem; font-weight:700; text-transform:uppercase; letter-spacing:0.15em; }
.split-worried .split-label { color:var(--red); }
.split-over .split-label { color:var(--green); }
.split-person-visual { width:300px; height:240px; border-radius:28px; overflow:hidden; position:relative; isolation:isolate; background:rgba(255,255,255,0.04); flex-shrink:0; }
.split-person-visual img { width:100%; height:100%; display:block; object-fit:cover; }
.split-person-overlay { position:absolute; inset:0; pointer-events:none; background:linear-gradient(180deg,rgba(7,11,23,0.02),rgba(7,11,23,0.55)); }
.split-person-visual.image-failed { background:rgba(255,255,255,0.04); }
.split-person-visual.image-failed img { display:none; }
.split-thought { font-size:1.5rem; color:var(--text-secondary); font-style:italic; max-width:260px; }
.split-tag { font-size:0.9rem; font-weight:600; opacity:0.7; }

/* === PROMPT CARDS === */
.prompt-card { background:linear-gradient(145deg,rgba(23,35,61,0.96),rgba(11,17,33,0.96)); border-radius:14px; padding:2rem; min-width:520px; max-width:700px; }
.prompt-generic { border:1px solid rgba(148,163,184,0.2); }
.prompt-contextual { border:1px solid rgba(34,211,238,0.4); box-shadow:0 0 30px rgba(34,211,238,0.08); }
.prompt-label { font-size:0.85rem; font-weight:700; text-transform:uppercase; letter-spacing:0.12em; margin-bottom:1rem; }
.prompt-label.generic { color:var(--text-muted); }
.prompt-label.contextual { color:var(--cyan); }
.prompt-text { font-size:1.4rem; color:var(--text-secondary); font-weight:300; line-height:1.6; font-style:italic; }
.prompt-result { font-size:1.15rem; margin-top:1rem; padding:0.8rem 1rem; border-radius:8px; }
.prompt-generic .prompt-result { background:rgba(255,255,255,0.03); }
.prompt-contextual .prompt-result { background:rgba(34,211,238,0.06); border-left:3px solid var(--cyan); }

/* === TOOL CONSTELLATION === */
.constellation { position:relative; width:1400px; height:950px; margin:0 auto; }
#scene-ai-ecosystem .constellation { margin:0; }
#scene-ai-ecosystem .constellation-center {
  position:absolute; left:50%; top:50%; transform:translate(-50%,-50%);
  z-index:3; display:flex; flex-direction:column; align-items:center; justify-content:center;
  width:min(760px,70%); text-align:center; pointer-events:none;
}
#scene-ai-ecosystem .constellation-center .slide-label { margin-bottom:1rem; }
#scene-ai-ecosystem .constellation-center .s-heading { margin:0; max-width:760px; line-height:1.15; }
#scene-ai-ecosystem .constellation-origin { position:absolute; left:50%; top:50%; width:0; height:0; z-index:2; }
#scene-ai-ecosystem #connections-canvas { z-index:0; }
#connections-canvas { position:absolute; inset:0; width:100%; height:100%; pointer-events:none; z-index:0; }
.tool-node {
  position:absolute; display:flex; flex-direction:column; align-items:center; gap:0.6rem;
  cursor:pointer; z-index:2; opacity:0;
  transform:translate(-50%,-50%);
}
.tool-node .tn-icon { width:80px; height:80px; border-radius:16px; display:flex; align-items:center; justify-content:center; border:1px solid rgba(255,255,255,0.12); background:rgba(17,26,46,0.9); }
.tool-node .tn-name { font-size:1.5rem; font-weight:700; color:var(--text-primary); white-space:nowrap; }
.tool-node .tn-cap { font-size:1.15rem; font-weight:500; color:var(--text-secondary); white-space:nowrap; }
.tool-node .tn-icon svg { width:40px; height:40px; }
.tool-node:hover .tn-icon { border-color:var(--gold); box-shadow:0 0 25px rgba(255,184,0,0.15); }

/* === 10/10 DISPLAY === */
.ten-display { display:flex; align-items:baseline; gap:0.8rem; margin:0.5rem 0; }
.ten-number { font-size:7rem; font-weight:900; color:var(--gold); line-height:1; }
.ten-label { font-size:1.8rem; color:var(--text-muted); font-weight:300; }

/* === SPOTLIGHT CARDS === */
.spotlight-card { background:linear-gradient(145deg,rgba(23,35,61,0.96),rgba(11,17,33,0.96)); border-radius:16px; padding:2.5rem; text-align:center; min-width:600px; border:1px solid rgba(255,255,255,0.08); }
.spotlight-card .sp-tag { font-size:0.9rem; font-weight:600; text-transform:uppercase; letter-spacing:0.1em; padding:0.4rem 1rem; border-radius:100px; display:inline-block; margin-bottom:1rem; }
.spotlight-card h3 { font-size:2.5rem; font-weight:700; margin-bottom:0.8rem; }
.spotlight-card p { font-size:1.5rem; color:var(--text-secondary); font-weight:300; line-height:1.5; }
.sp-design .sp-tag { color:var(--violet); background:rgba(139,92,246,0.12); }
.sp-code .sp-tag { color:var(--cyan); background:rgba(34,211,238,0.12); }
.sp-multi .sp-tag { color:var(--gold); background:rgba(255,184,0,0.12); }

/* === CHALLENGE TRIANGLE === */
.challenge-triangle { display:grid; grid-template-columns:1fr 1fr; gap:2rem; align-items:center; }
.ct-item { text-align:center; padding:1.2rem 2rem; border-radius:14px; background:linear-gradient(145deg,rgba(23,35,61,0.96),rgba(11,17,33,0.96)); }
.ct-item p { font-size:1.15rem; color:var(--text-muted); margin-top:0.3rem; }
.ct-top { grid-column:1/-1; }
.ct-gold { border:1px solid rgba(255,184,0,0.35); box-shadow:0 0 20px rgba(255,184,0,0.08); }
.ct-cyan { border:1px solid rgba(34,211,238,0.35); box-shadow:0 0 20px rgba(34,211,238,0.08); }
.ct-green { border:1px solid rgba(34,197,94,0.35); box-shadow:0 0 20px rgba(34,197,94,0.08); }
.ct-gold .big-number-sm { color:var(--gold); }
.ct-cyan .big-number-sm { color:var(--cyan); }
.ct-green .big-number-sm { color:var(--green); }

/* === NOUN LIST === */
.nouns-list { display:flex; flex-direction:column; gap:0.5rem; }
.nouns-list span { font-size:2.8rem; font-weight:300; color:#64758B; }

/* === QUESTION LIST === */
.questions-list { display:flex; flex-direction:column; gap:0.8rem; }
.questions-list span { font-size:1.8rem; font-weight:400; padding:0.3rem 0; line-height:1.4; }

/* === EQUATION DISPLAY (DANGER) === */
.equation-display { display:flex; align-items:center; gap:1rem; justify-content:center; }
.eq-part { font-size:9rem; font-weight:900; letter-spacing:-0.04em; line-height:1; }
.eq-one { color:var(--text-primary); }
.eq-op { font-size:5rem; color:var(--red); opacity:0.5; }
.eq-tenk { color:var(--red); text-shadow:0 0 40px rgba(239,68,68,0.3); }
.eq-caption { font-size:1.6rem; color:var(--text-muted); font-weight:300; margin-top:1rem; }
.danger-grid { display:flex; flex-wrap:wrap; gap:1.2rem; justify-content:center; margin-top:1.5rem; width:100%; }
.d-node { display:flex; align-items:center; gap:0.8rem; padding:0.8rem 1.5rem; border-radius:10px; font-size:1.4rem; color:var(--text-secondary); background:linear-gradient(145deg,rgba(23,35,61,0.96),rgba(11,17,33,0.96)); }
.d-node .d-icon { display:inline-flex; align-items:center; justify-content:center; width:24px; height:24px; }
.d-node .d-icon svg { width:18px; height:18px; }
.d-node.d-hallucination { border:1px solid rgba(239,68,68,0.35); }
.d-node.d-security { border:1px solid rgba(249,115,22,0.35); }
.d-node.d-scaling { border:1px solid rgba(239,68,68,0.35); }
.d-node.d-confidence { border:1px solid rgba(249,115,22,0.35); }

/* === UPDATE STACK === */
.update-stack { display:flex; flex-direction:column; gap:1rem; }
.update-item { font-size:3rem; font-weight:500; color:var(--text-secondary); line-height:1.4; }

/* === FINAL QUESTION === */
.final-question { font-size:7.5rem; font-weight:900; color:var(--text-primary); text-align:center; line-height:1.15; max-width:90%; }

/* === FINAL BLOCK === */
.final-block p { font-size:2rem; color:var(--text-secondary); font-weight:300; line-height:1.5; max-width:85%; margin:0 auto 1.2rem; }
.final-block .fq { font-size:2.8rem; }
.final-block .fq-main { font-size:4.5rem; font-weight:700; }

/* === THANK YOU === */
.thank-you-text { font-size:6rem; font-weight:700; color:var(--gold); text-align:center; text-shadow:0 0 30px rgba(255,184,0,0.15); }

/* === AMBIENT GLOWS === */
.ambient-glow {
  position:absolute;
  pointer-events:none;
  z-index:1;
  border-radius:50%;
  transform:translate(-50%,-50%);
  filter:blur(120px);
}
.glow-gold   { width:2400px; height:2400px; background:radial-gradient(ellipse,rgba(255,184,0,0.10),transparent 60%); }
.glow-cyan   { width:2200px; height:2200px; background:radial-gradient(ellipse,rgba(34,211,238,0.08),transparent 60%); }
.glow-violet { width:2200px; height:2200px; background:radial-gradient(ellipse,rgba(139,92,246,0.08),transparent 60%); }
.glow-blue   { width:2400px; height:2400px; background:radial-gradient(ellipse,rgba(59,130,246,0.08),transparent 60%); }
.glow-green  { width:2000px; height:2000px; background:radial-gradient(ellipse,rgba(34,197,94,0.07),transparent 60%); }
.glow-red    { width:2200px; height:2200px; background:radial-gradient(ellipse,rgba(239,68,68,0.08),transparent 60%); }
.glow-orange { width:2200px; height:2200px; background:radial-gradient(ellipse,rgba(249,115,22,0.08),transparent 60%); }

/* === PARALLAX === */
#parallax-back {
  background:radial-gradient(ellipse 60% 50% at 20% 30%,rgba(7,11,23,0.7),transparent),radial-gradient(ellipse 40% 40% at 80% 70%,rgba(17,26,46,0.3),transparent);
  opacity:0.7;
}
#parallax-mid {
  background:radial-gradient(ellipse 50% 30% at 50% 20%,rgba(255,184,0,0.02),transparent),radial-gradient(ellipse 30% 40% at 70% 80%,rgba(34,211,238,0.02),transparent);
  opacity:0.4;
}

/* === HUD === */
#hud {
  position:fixed; bottom:2rem; left:50%; transform:translateX(-50%);
  display:flex; align-items:center; gap:1rem;
  z-index:1000;
  opacity:1;
  transition:opacity 0.5s ease;
}
#hud.hud-hidden { opacity:0.15; }
#hud.hud-hidden:hover { opacity:1; }
.hud-btn {
  background:rgba(17,26,46,0.85); border:1px solid rgba(255,255,255,0.08);
  color:var(--gold); font-size:1.2rem;
  width:40px; height:40px; border-radius:50%;
  cursor:pointer; display:flex; align-items:center; justify-content:center;
  transition:background 0.2s; font-family:inherit;
}
.hud-btn:hover { background:rgba(255,184,0,0.12); }
.hud-btn-sm { width:32px; height:32px; font-size:0.9rem; }
#progress-bar { width:120px; height:2px; background:rgba(255,255,255,0.06); border-radius:2px; overflow:hidden; }
#progress-fill { height:100%; width:0%; background:var(--gold); transition:width 0.4s ease; }

/* === ZONE LABELS === */
#zone-labels {
  position:fixed; inset:0;
  display:flex; flex-wrap:wrap; align-items:center; justify-content:center;
  gap:3rem;
  pointer-events:none;
  z-index:500;
  opacity:0;
  transition:opacity 0.6s ease;
}
#zone-labels.active { opacity:1; pointer-events:auto; }
.zl-item {
  font-size:1.4rem; font-weight:700; color:var(--text-muted);
  text-transform:uppercase; letter-spacing:0.08em;
  cursor:pointer; padding:0.5rem 1.5rem; border:1px solid rgba(255,255,255,0.06);
  border-radius:8px; transition:all 0.3s; background:rgba(7,11,23,0.85);
}
.zl-item:hover { color:var(--gold); border-color:var(--gold); background:rgba(255,184,0,0.06); }

/* === PARTICLES === */
#particle-canvas { position:fixed; inset:0; width:100%; height:100%; pointer-events:none; z-index:999; opacity:0; transition:opacity 0.8s ease; }
#particle-canvas.active { opacity:1; }

/* === KEYFRAMES === */
@keyframes elasticBounce {
  0%{transform:scale(0.2);opacity:0}
  50%{transform:scale(1.12)}
  70%{transform:scale(0.9)}
  85%{transform:scale(1.05)}
  100%{transform:scale(1);opacity:1}
}
.elastic-bounce { animation:elasticBounce 1.2s cubic-bezier(0.68,-0.55,0.27,1.55) forwards; }
@keyframes fadeUp { from{opacity:0;transform:translateY(20px)} to{opacity:1;transform:translateY(0)} }
.fade-up { animation:fadeUp 0.7s ease forwards; }
@keyframes slideInLeft { from{transform:translateX(-100%);opacity:0} to{transform:translateX(0);opacity:1} }
@keyframes slideInRight { from{transform:translateX(-100%);opacity:0} to{transform:translateX(0);opacity:1} }
@keyframes pulseGlow {
  0%,100%{text-shadow:0 0 20px rgba(255,184,0,0.3),0 0 40px rgba(255,184,0,0.1)}
  50%{text-shadow:0 0 40px rgba(255,184,0,0.5),0 0 80px rgba(255,184,0,0.2)}
}
.word-fade span { display:inline-block; opacity:0; transition:opacity 0.4s ease; }

/* === RESPONSIVE === */
@media (max-width:1024px) {
  .scene-inner { min-width:380px; max-width:600px; padding:1.5rem; }
  h1,.s-title { font-size:4rem!important; }
  .s-question { font-size:2.8rem; }
  .s-bigquestion { font-size:3rem; }
  .big-number { font-size:5rem; }
  .big-number-sm { font-size:3.5rem; }
  .s-heading { font-size:2.2rem; }
  .s-statement { font-size:1.8rem; }
  .s-question-sm { font-size:2rem; }
  .final-question { font-size:4.5rem; }
  .final-block .fq-main { font-size:3rem; }
  .thank-you-text { font-size:4rem; }
  .quote-card .q-main { font-size:2.2rem; }
  .limits-grid { flex-wrap:wrap; justify-content:center; }
  .limits-grid .limit-item { flex-basis:40%; }
  .b-items { flex-direction:column; align-items:center; }
  .b-items span { font-size:2rem; }
  .constellation { width:700px; height:600px; }
  .tool-node .tn-icon { width:56px; height:56px; }
  .tool-node .tn-icon svg { width:28px; height:28px; }
  .tool-node .tn-name { font-size:1.1rem; }
  .tool-node .tn-cap { font-size:0.85rem; }
  .ten-number { font-size:4.5rem; }
  .eq-part { font-size:5rem; }
  .split-view { flex-direction:column; }
  .split-side { min-width:auto; }
  .nouns-list span { font-size:2rem; }
  .questions-list span { font-size:1.3rem; }
  .prompt-card { min-width:360px; max-width:500px; }
  .spotlight-card { min-width:400px; }
  .d-node { font-size:1.1rem; }
  .update-item { font-size:2rem; }
  .eq-part { font-size:6rem; }
}
@media (max-width:768px) {
  .scene-inner { min-width:260px; max-width:420px; padding:1.2rem; }
  h1,.s-title { font-size:2.8rem!important; }
  .s-question { font-size:2rem; }
  .s-bigquestion { font-size:2.2rem; }
  .big-number { font-size:3.5rem; }
  .constellation { width:360px; height:380px; }
  .tool-node .tn-icon { width:40px; height:40px; }
  .tool-node .tn-icon svg { width:20px; height:20px; }
  .tool-node .tn-name { font-size:0.8rem; }
  .tool-node .tn-cap { display:none; }
  .update-item { font-size:1.6rem; }
  .final-question { font-size:3rem; }
  .final-block .fq-main { font-size:2.2rem; }
  .thank-you-text { font-size:3rem; }
  .ten-number { font-size:3rem; }
  .eq-part { font-size:3.5rem; }
  .prompt-card { min-width:220px; max-width:360px; }
  .spotlight-card { min-width:240px; }
  #hud { bottom:1rem; gap:0.6rem; }
  #progress-bar { width:60px; }
  .zl-item { font-size:0.9rem; padding:0.3rem 1rem; }
  .d-node { font-size:0.9rem; }
  .limit-visual { width:120px; height:120px; }
}
@media (prefers-reduced-motion:reduce) {
  *,*::before,*::after { animation-duration:0.01ms!important; transition-duration:0.01ms!important; }
  .gold-line::after { animation:none; background:var(--gold); }
  .b-arrow { animation:none; }
}

