84	/* ===== ECOSYSTEM CAMERA TARGET ===== */
85	function getSceneCameraTarget(index) {
86	  var s = scenes[index];
87	  if (index !== 21) return { x: s.x, y: s.y };
88	  var el = document.getElementById('scene-' + s.id);
89	  if (!el) return { x: s.x, y: s.y };
90	  var elements = [];
91	  var center = el.querySelector('.constellation-center');
92	  if (center) elements.push(center);
93	  var nodes = el.querySelectorAll('.tool-node');
94	  nodes.forEach(function(n) { elements.push(n); });
95	  var minL = Infinity, minT = Infinity, maxR = -Infinity, maxB = -Infinity;
96	  for (var i = 0; i < elements.length; i++) {
97	    var r = elements[i].getBoundingClientRect();
98	    if (r.width === 0 && r.height === 0) continue;
99	    minL = Math.min(minL, r.left); minT = Math.min(minT, r.top);
100	    maxR = Math.max(maxR, r.right); maxB = Math.max(maxB, r.bottom);
101	  }
102	  if (minL === Infinity) return { x: s.x, y: s.y };
103	  var cCX = (minL + maxR) / 2, cCY = (minT + maxB) / 2;
104	  var vw = window.innerWidth, vh = window.innerHeight;
105	  return {
106	    x: (cCX - vw / 2) / camera.z + camera.x,
107	    y: (cCY - vh / 2) / camera.z + camera.y
108	  };
109	}
