121	function goToScene(index, playEntrance) {
122	  if (index < 0 || index >= scenes.length) return;
123	  if (overviewActive) { exitOverview(); }
124	  if (currentNavTimeline) { currentNavTimeline.kill(); currentNavTimeline = null; }
125	
126	  var fromIndex = currentScene;
127	  var fromEl = document.getElementById('scene-' + scenes[fromIndex].id);
128	  var targetEl = document.getElementById('scene-' + scenes[index].id);
129	  if (!fromEl || !targetEl) return;
130	  var navId = ++navVersion;
131	
132	  // Clean stale states
133	  document.querySelectorAll('.scene').forEach(function(el) {
134	    el.classList.remove('is-entering', 'is-leaving');
135	  });
136	
137	  triggerSceneLeave(fromIndex);
138	
139	  // Measure content bounds BEFORE prepare (avoids GSAP entrance scale distorting rects)
140	  targetEl.classList.add('is-measuring');
141	  var bounds = getSceneContentBounds(targetEl);
142	  targetEl.classList.remove('is-measuring');
143	
144	  // PREPARE target entrance state while still hidden
145	  prepareSceneForEnter(index);
146	
147	  // Calculate safe zoom and camera target
148	  var s = scenes[index];
149	  var preferredZ = s.z;
150	  var finalZ = calculateSafeFitZoom(bounds.width, bounds.height, preferredZ);
151	  var camTarget = getSceneCameraTarget(index);
152	
153	  var settled = false;
154	  var isEntrancePlayed = false;
155	
156	  function entranceCallback() {
157	    if (navId !== navVersion) return;
158	    if (isEntrancePlayed) return;
159	    isEntrancePlayed = true;
160	    if (playEntrance !== false) { triggerSceneEnter(index); }
161	    else { forceSceneFinalState(index); }
162	  }
163	
164	  function completeCallback() {
165	    if (navId !== navVersion) return;
166	    if (settled) return;
167	    settled = true;
168	    fromEl.classList.remove('is-leaving');
169	    targetEl.classList.remove('is-entering');
170	    setActiveScene(index);
171	    currentScene = index;
172	    currentNavTimeline = null;
173	    updateProgress();
174	  }
175	
176	  if (playEntrance === false) {
177	    // Instant/final state — used by audit
178	    gsap.killTweensOf(camera);
179	    camera.x = camTarget.x; camera.y = camTarget.y; camera.z = finalZ; camera.r = s.r || 0;
180	    applyCameraTransform();
181	    fromEl.classList.remove('is-leaving');
182	    targetEl.classList.remove('is-entering');
183	    setActiveScene(index);
184	    currentScene = index;
185	    forceSceneFinalState(index);
186	    updateProgress();
187	    return;
188	  }
189	
190	  var dur = reduceMotion ? 0.001 : (s.d || 1.5);
191	
192	  // Mark states
193	  fromEl.classList.add('is-leaving');
194	  targetEl.classList.add('is-entering');
195	
196	  currentNavTimeline = gsap.timeline({onComplete: completeCallback});
197	
198	  // Departure fade: from scene over first 30%
199	  if (!reduceMotion) {
200	    currentNavTimeline.to(fromEl, {opacity:0, duration:dur*0.30, ease:'power2.in'}, 0);
201	  } else {
202	    gsap.set(fromEl, {opacity:0});
203	  }
204	
205	  // Camera movement: full duration
206	  currentNavTimeline.to(camera, {
207	    x: camTarget.x, y: camTarget.y, z: finalZ, r: s.r || 0,
208	    duration: dur, ease: 'power3.inOut',
209	    onUpdate: applyCameraTransform
210	  }, 0);
211	
212	  // Entrance trigger
213	  var entranceTime = reduceMotion ? 0 : (isImpactScene(index) ? dur : dur * 0.80);
214	  currentNavTimeline.addLabel('sceneEnter', entranceTime);
215	  currentNavTimeline.call(entranceCallback, null, 'sceneEnter');
216	}
