369	/* ===== SCENE CONTENT BOUNDS MEASUREMENT ===== */
370	function getSceneContentBounds(el) {
371	  var inner = el.querySelector('.scene-inner');
372	  if (!inner) return {width:600, height:400};
373	
374	  var elements = [];
375	
376	  // Scoped: AI ecosystem — measure semantic content only, not constellation border box
377	  if (el.id === 'scene-ai-ecosystem') {
378	    var centerEl = el.querySelector('.constellation-center');
379	    if (centerEl) elements.push(centerEl);
380	    var toolNodes = el.querySelectorAll('.tool-node');
381	    toolNodes.forEach(function(n) { elements.push(n); });
382	  } else {
383	    // 1. Direct children of .scene-inner (main content blocks)
384	    var children = inner.children;
385	    for (var i = 0; i < children.length; i++) {
386	      elements.push(children[i]);
387	    }
388	
389	    // 2. Absolutely positioned .tool-node descendants that may overflow their parent
390	    var toolNodes = inner.querySelectorAll('.tool-node');
391	    for (var i = 0; i < toolNodes.length; i++) {
392	      if (elements.indexOf(toolNodes[i]) === -1) {
393	        elements.push(toolNodes[i]);
394	      }
395	    }
396	  }
397	
398	  // 3. Temporarily neutralize GSAP entrance transforms on measured elements
399	  //    (scale affects getBoundingClientRect dimensions; translate/opacity do not)
400	  var scaleSaves = [];
401	  for (var i = 0; i < elements.length; i++) {
402	    var e = elements[i];
403	    var s = gsap.getProperty(e, 'scale');
404	    if (s !== undefined && Math.abs(s - 1) > 0.01) {
405	      scaleSaves.push({el:e, scale:s});
406	      gsap.set(e, {scale:1, overwrite:'auto'});
407	    }
408	  }
409	
410	  // 4. Compute union bounding rect
411	  var minLeft = Infinity, minTop = Infinity;
412	  var maxRight = -Infinity, maxBottom = -Infinity;
413	
414	  for (var i = 0; i < elements.length; i++) {
415	    var child = elements[i];
416	    var cs = getComputedStyle(child);
417	    if (cs.display === 'none') continue;
418	    var rect = child.getBoundingClientRect();
419	    if (rect.width === 0 && rect.height === 0) continue;
420	    minLeft = Math.min(minLeft, rect.left);
421	    minTop = Math.min(minTop, rect.top);
422	    maxRight = Math.max(maxRight, rect.right);
423	    maxBottom = Math.max(maxBottom, rect.bottom);
424	  }
425	
426	  // 5. Restore GSAP entrance transforms
427	  for (var i = 0; i < scaleSaves.length; i++) {
428	    gsap.set(scaleSaves[i].el, {scale:scaleSaves[i].scale, overwrite:'auto'});
429	  }
430	
431	  if (minLeft === Infinity) {
432	    return {width:inner.scrollWidth||600, height:inner.scrollHeight||400};
433	  }
434	
435	  // Correct for camera transform (getBoundingClientRect includes camera zoom/translate)
436	  var currentZoom = camera.z || 1;
437	  var visualW = (maxRight - minLeft) / currentZoom;
438	  var visualH = (maxBottom - minTop) / currentZoom;
439	
440	  return {width:visualW, height:visualH};
441	}
442	
443	/* ===== SAFE-FIT ZOOM ===== */
444	function calculateSafeFitZoom(contentW, contentH, preferredZ) {
445	  var safeW = window.innerWidth * 0.88;
446	  var safeH = window.innerHeight * 0.80;
447	  var fitX = safeW / contentW;
448	  var fitY = safeH / contentH;
449	  var safeZ = Math.min(fitX, fitY);
450	  safeZ = Math.max(0.15, Math.min(2.5, safeZ));
451	  return Math.min(preferredZ, safeZ);
452	}
