645	/* ===== WORD-BY-WORD FADE ===== */
646	function animateWordFade(element, delayPerWord) {
647	  if (!element) return;
648	  if (element.dataset.wfDone === '1') return;
649	  element.dataset.wfDone = '1';
650	
651	  var delayPerWordMs = delayPerWord || 300;
652	  var wordIndex = 0;
653	
654	  function processText(text, target) {
655	    if (!text) return;
656	    var parts = text.split(/(\s+)/);
657	    for (var p = 0; p < parts.length; p++) {
658	      var part = parts[p];
659	      if (!part) continue;
660	      if (part.trim() === '') {
661	        target.appendChild(document.createTextNode(part));
662	      } else {
663	        var idx = wordIndex++;
664	        var span = document.createElement('span');
665	        span.textContent = part;
666	        span.dataset.wf = '1';
667	        span.style.opacity = '0';
668	        span.style.transition = 'opacity 0.5s ease ' + (idx * delayPerWordMs) + 'ms';
669	        target.appendChild(span);
670	        (function(el, d) {
671	          setTimeout(function() { el.style.opacity = '1'; }, 100 + d);
672	        })(span, idx * delayPerWordMs);
673	      }
674	    }
675	  }
676	
677	  function processNode(node, target) {
678	    if (node.nodeType === 3) {
679	      processText(node.textContent, target);
680	    } else if (node.nodeType === 1) {
681	      if (node.tagName === 'BR') {
682	        target.appendChild(document.createElement('br'));
683	        return;
684	      }
685	      var clone = document.createElement(node.tagName);
686	      for (var a = 0; a < node.attributes.length; a++) {
687	        clone.setAttribute(node.attributes[a].name, node.attributes[a].value);
688	      }
689	      for (var c = 0; c < node.childNodes.length; c++) {
690	        processNode(node.childNodes[c], clone);
691	      }
692	      target.appendChild(clone);
693	    }
694	  }
695	
696	  var fragment = document.createDocumentFragment();
697	  var childNodes = Array.prototype.slice.call(element.childNodes);
698	  for (var i = 0; i < childNodes.length; i++) {
699	    processNode(childNodes[i], fragment);
700	  }
701	  element.innerHTML = '';
702	  element.appendChild(fragment);
703	}
