705	/* ===== TOOL CONNECTION LINES ===== */
706	function drawConnections() {
707	  var container = document.getElementById('constellation');
708	  if (!container) return;
709	  connCanvas = document.getElementById('connections-canvas');
710	  if (!connCanvas) return;
711	  connCtx = connCanvas.getContext('2d');
712	  var rect = container.getBoundingClientRect();
713	  connCanvas.width = container.offsetWidth || 900;
714	  connCanvas.height = container.offsetHeight || 650;
715	  if (connDrawn) return;
716	  connDrawn = true;
717	
718	  var toolEls = container.querySelectorAll('.tool-node');
719	  var positions = [];
720	  var toolColors = {
721	    'opencode':     {r:34,  g:211, b:238},
722	    'ollama':       {r:139, g:92,  b:246},
723	    'n8n':          {r:249, g:115, b:22},
724	    'crewai':       {r:236, g:72,  b:153},
725	    'comfyui':      {r:236, g:72,  b:153},
726	    'browseruse':   {r:34,  g:211, b:238},
727	    'hyperbrowser': {r:59,  g:130, b:246},
728	    'openhands':    {r:34,  g:197, b:94},
729	    'tmux':         {r:255, g:184, b:0},
730	    'design-tool':  {r:139, g:92,  b:246}
731	  };
732	  var canvasRect = connCanvas.getBoundingClientRect();
733	  var scaleX = connCanvas.width / canvasRect.width;
734	  var scaleY = connCanvas.height / canvasRect.height;
735	  toolEls.forEach(function(el) {
736	    var nodeRect = el.getBoundingClientRect();
737	    var cssCX = nodeRect.left - canvasRect.left + nodeRect.width / 2;
738	    var cssCY = nodeRect.top - canvasRect.top + nodeRect.height / 2;
739	    positions.push({x: cssCX * scaleX, y: cssCY * scaleY});
740	  });
741	
742	  var alpha = 0.06;
743	  function drawLine() {
744	    if (!connCtx) return;
745	    connCtx.clearRect(0, 0, connCanvas.width, connCanvas.height);
746	    for (var i = 0; i < positions.length; i++) {
747	      for (var j = i + 1; j < positions.length; j++) {
748	        var dx = positions[i].x - positions[j].x;
749	        var dy = positions[i].y - positions[j].y;
750	        var dist = Math.sqrt(dx*dx + dy*dy);
751	        if (dist < 600) {
752	          var tool1 = toolEls[i].getAttribute('data-tool');
753	          var tc = toolColors[tool1] || {r:255,g:184,b:0};
754	          connCtx.beginPath();
755	          connCtx.moveTo(positions[i].x, positions[i].y);
756	          connCtx.lineTo(positions[j].x, positions[j].y);
757	          connCtx.strokeStyle = 'rgba('+tc.r+','+tc.g+','+tc.b+','+(alpha * (1 - dist/600))+')';
758	          connCtx.lineWidth = 0.6;
759	          connCtx.stroke();
760	        }
761	      }
762	    }
763	    if (alpha < 0.2) {
764	      alpha += 0.005;
765	      requestAnimationFrame(drawLine);
766	    }
767	  }
768	  drawLine();
769	}
