779	function createParticles(count) {
780	  particles = [];
781	  for (var i = 0; i < count; i++) {
782	    particles.push({
783	      x: Math.random() * particleCanvas.width,
784	      y: Math.random() * particleCanvas.height,
785	      vx: (Math.random() - 0.5) * 0.3,
786	      vy: (Math.random() - 0.5) * 0.3 - 0.1,
787	      r: Math.random() * 2.5 + 0.5,
788	      baseOpacity: Math.random() * 0.4 + 0.1,
789	      life: Math.random() * 120 + 60,
790	      maxLife: Math.random() * 120 + 60,
791	      drift: Math.sin(Math.random() * Math.PI * 2) * 0.08
792	    });
793	  }
794	}
795	
796	function animateParticles() {
797	  if (!particleActive) {
798	    pCtx.clearRect(0, 0, particleCanvas.width, particleCanvas.height);
799	    pRaf = null;
800	    return;
801	  }
802	  pCtx.clearRect(0, 0, particleCanvas.width, particleCanvas.height);
803	  for (var i = 0; i < particles.length; i++) {
804	    var p = particles[i];
805	    p.x += p.vx + Math.sin(p.life * 0.02) * p.drift;
806	    p.y += p.vy;
807	    p.life--;
808	    var opacity = p.baseOpacity * Math.min(1, (p.life / p.maxLife) * 2);
809	    if (p.life <= 0) {
810	      p.x = Math.random() * particleCanvas.width;
811	      p.y = particleCanvas.height + 10;
812	      p.life = p.maxLife = Math.random() * 120 + 60;
813	      p.baseOpacity = Math.random() * 0.4 + 0.1;
814	      p.r = Math.random() * 2.5 + 0.5;
815	    }
816	    pCtx.beginPath();
817	    pCtx.arc(p.x, p.y, p.r, 0, Math.PI * 2);
818	    pCtx.fillStyle = 'rgba(255, 179, 0, ' + opacity + ')';
819	    pCtx.fill();
820	  }
821	  pRaf = requestAnimationFrame(animateParticles);
822	}
