1045	/* ===== SCENE FRAMING AUDIT ===== */
1046	function auditSceneFraming() {
1047	  var safeW = window.innerWidth * 0.88;
1048	  var safeH = window.innerHeight * 0.80;
1049	  var VW = window.innerWidth;
1050	  var VH = window.innerHeight;
1051	  var results = [];
1052	
1053	  for (var i = 0; i < scenes.length; i++) {
1054	    var s = scenes[i];
1055	    // Navigate instantly without entrance
1056	    goToScene(i, false);
1057	    // Force final state
1058	    forceSceneFinalState(i);
1059	    // Measure
1060	    var el = document.getElementById('scene-' + s.id);
1061	    var inner = el ? el.querySelector('.scene-inner') : null;
1062	    var cw = 0, ch = 0;
1063	    if (inner) { cw = inner.scrollWidth || 0; ch = inner.scrollHeight || 0; }
1064	    var renderedW = cw * camera.z;
1065	    var renderedH = ch * camera.z;
1066	    var leftClip = renderedW > safeW ? 1 : 0;
1067	    var topClip = renderedH > safeH ? 1 : 0;
1068	    var rightClip = leftClip;
1069	    var bottomClip = topClip;
1070	    var hudOverlap = (camera.y + (ch * camera.z)/2 + 20) > (VH - 60) ? 1 : 0;
1071	
1072	    // Check inactive scene leaks
1073	    var inactiveLeak = 0;
1074	    document.querySelectorAll('.scene').forEach(function(other) {
1075	      if (other === el) return;
1076	      if (other.style.visibility === 'visible' || other.classList.contains('is-active') || other.classList.contains('is-entering')) {
1077	        var rect = other.getBoundingClientRect();
1078	        if (rect.right > 0 && rect.left < VW && rect.bottom > 0 && rect.top < VH) {
1079	          inactiveLeak = 1;
1080	        }
1081	      }
1082	    });
1083	
1084	    var status = (leftClip + topClip + rightClip + bottomClip + hudOverlap + inactiveLeak === 0) ? 'PASS' : 'FAIL';
1085	    results.push({
1086	      index:i, scene:s.id, zoom:camera.z.toFixed(3),
1087	      contentW:cw, contentH:ch,
1088	      renderedW:Math.round(renderedW), renderedH:Math.round(renderedH),
1089	      leftClip:leftClip, topClip:topClip, rightClip:rightClip, bottomClip:bottomClip,
1090	      hudOverlap:hudOverlap, inactiveLeak:inactiveLeak,
1091	      status:status
1092	    });
1093	  }
1094	  console.table(results);
1095	  var pass = results.filter(function(r){return r.status==='PASS';}).length;
1096	  console.log('Audit: ' + pass + '/' + results.length + ' PASS');
1097	  return results;
1098	}
