  {id:'rs-5000',              x:4500,   y:2000,  z:1.2,  r:0,   d:1.2, label:'LIVE CHALLENGE'},
  {id:'7-days',               x:4200,   y:2600,  z:1.2,  r:3,   d:1.2},
  {id:'rs-1000',              x:4800,   y:2600,  z:1.2,  r:-3,  d:1.2},
  {id:'challenge-overview',   x:4500,   y:2300,  z:0.55, r:0,   d:1.6},
  {id:'nouns',                x:5800,   y:100,   z:0.85, r:0,   d:1.3, label:'EXECUTION'},
  {id:'questions',            x:6600,   y:100,   z:0.85, r:2,   d:1.4},
  {id:'execution-quote',      x:6200,   y:600,   z:1.1,  r:0,   d:1.5},
  {id:'generic-prompt',       x:-1200,  y:1400,  z:0.8,  r:0,   d:1.3, label:'AI DEMO'},
  {id:'contextual-prompt',    x:-400,   y:1400,  z:0.85, r:0,   d:1.5},
  {id:'what-changed',         x:-800,   y:2000,  z:0.65, r:0,   d:1.4},
  {id:'direction-missing',    x:-800,   y:2500,  z:1.2,  r:0,   d:2.0},
  {id:'ai-ecosystem',         x:-2500,  y:-800,  z:0.4,  r:0,   d:2.0, label:'AI ECOSYSTEM'},
  {id:'ten-ten',              x:-2000,  y:-1400, z:0.8,  r:0,   d:1.5},
  {id:'ai-design',            x:-1800,  y:-500,  z:1.3,  r:0,   d:1.3},
  {id:'opencode',             x:-1400,  y:-500,  z:1.3,  r:0,   d:1.3},
  {id:'multi-agent',          x:-1000,  y:-500,  z:1.3,  r:0,   d:1.3},
  {id:'cost-collapsing',      x:-2500,  y:100,   z:0.95, r:0,   d:1.6},
  {id:'risk-overview',        x:-3200,  y:2200,  z:0.75, r:0,   d:1.6, label:'DANGER'},
  {id:'one-x-ten-thousand',   x:-2600,  y:2800,  z:1.0,  r:0,   d:2.0},
  {id:'without-judgment',     x:-3000,  y:3400,  z:1.0,  r:0,   d:1.8},
  {id:'updates',              x:-3500,  y:-2000, z:0.55, r:0,   d:1.8, label:'FINAL QUESTION'},
  {id:'when-updated',         x:-3000,  y:-2400, z:1.5,  r:0,   d:2.5},
  {id:'final-message',        x:-500,   y:-2000, z:0.65, r:0,   d:1.8},
  {id:'choose-questions',     x:0,      y:-1500, z:1.0,  r:0,   d:2.0},
  {id:'thank-you',            x:200,    y:-1000, z:0.7,  r:0,   d:2.5}
];

/* ===== DOM REFS ===== */
var world = document.getElementById('world');
var viewport = document.getElementById('viewport');
var parallaxBack = document.getElementById('parallax-back');
var parallaxMid = document.getElementById('parallax-mid');
var particleCanvas = document.getElementById('particle-canvas');
var pCtx = particleCanvas.getContext('2d');
var progressFill = document.getElementById('progress-fill');
var zoneLabels = document.getElementById('zone-labels');
var hud = document.getElementById('hud');

/* ===== CAMERA STATE ===== */
var camera = { x: scenes[0].x, y: scenes[0].y, z: scenes[0].z, r: scenes[0].r || 0 };
var currentScene = 0;
var isAnimating = false;
var overviewActive = false;
var prevOverviewScene = 0;
var particleActive = false;
var pRaf = null;
var particles = [];
var typewriterDone = false;
var sceneAnimations = {};
var connCanvas = null;
var connCtx = null;
var connDrawn = false;
var navVersion = 0;
var currentNavTimeline = null;
var originalFinalQuestionHTML = '';
var impactScenes = [6, 9, 10, 11, 12, 28, 31, 33, 34];
function isImpactScene(i) { return impactScenes.indexOf(i) >= 0; }

/* ===== CAMERA ENGINE ===== */
function applyCameraTransform() {
  var vw = window.innerWidth;
  var vh = window.innerHeight;
  world.style.transform = 'translate3d('+(vw/2)+'px,'+(vh/2)+'px,0) scale('+camera.z+') rotate('+(camera.r||0)+'deg) translate3d('+(-camera.x)+'px,'+(-camera.y)+'px,0)';
  var pOffX = (camera.x) * 0.08;
  var pOffY = (camera.y) * 0.08;
  parallaxBack.style.transform = 'translate3d('+(-pOffX)+'px,'+(-pOffY)+'px,0)';
  var mOffX = (camera.x) * 0.25;
  var mOffY = (camera.y) * 0.25;
  parallaxMid.style.transform = 'translate3d('+(-mOffX)+'px,'+(-mOffY)+'px,0)';
}

/* ===== ECOSYSTEM CAMERA TARGET ===== */
function getSceneCameraTarget(index) {
  var s = scenes[index];
  if (index !== 21) return { x: s.x, y: s.y };
  var el = document.getElementById('scene-' + s.id);
  if (!el) return { x: s.x, y: s.y };
  var elements = [];
  var center = el.querySelector('.constellation-center');
  if (center) elements.push(center);
  var nodes = el.querySelectorAll('.tool-node');
  nodes.forEach(function(n) { elements.push(n); });
  var minL = Infinity, minT = Infinity, maxR = -Infinity, maxB = -Infinity;
  for (var i = 0; i < elements.length; i++) {
    var r = elements[i].getBoundingClientRect();
    if (r.width === 0 && r.height === 0) continue;
    minL = Math.min(minL, r.left); minT = Math.min(minT, r.top);
    maxR = Math.max(maxR, r.right); maxB = Math.max(maxB, r.bottom);
  }
  if (minL === Infinity) return { x: s.x, y: s.y };
  var cCX = (minL + maxR) / 2, cCY = (minT + maxB) / 2;
  var vw = window.innerWidth, vh = window.innerHeight;
  return {
    x: (cCX - vw / 2) / camera.z + camera.x,
    y: (cCY - vh / 2) / camera.z + camera.y
  };
}

/* ===== SCENE STATE MANAGEMENT ===== */
function setActiveScene(index) {
  document.querySelectorAll('.scene').forEach(function(el) {
    el.classList.remove('is-active', 'is-entering', 'is-leaving');
    el.style.opacity = '';
  });
  var el = document.getElementById('scene-' + scenes[index].id);
  if (el) el.classList.add('is-active');
}

function goToScene(index, playEntrance) {
  if (index < 0 || index >= scenes.length) return;
  if (overviewActive) { exitOverview(); }
  if (currentNavTimeline) { currentNavTimeline.kill(); currentNavTimeline = null; }

  var fromIndex = currentScene;
  var fromEl = document.getElementById('scene-' + scenes[fromIndex].id);
  var targetEl = document.getElementById('scene-' + scenes[index].id);
  if (!fromEl || !targetEl) return;
  var navId = ++navVersion;

  // Clean stale states
  document.querySelectorAll('.scene').forEach(function(el) {
    el.classList.remove('is-entering', 'is-leaving');
  });

  triggerSceneLeave(fromIndex);

  // Measure content bounds BEFORE prepare (avoids GSAP entrance scale distorting rects)
  targetEl.classList.add('is-measuring');
  var bounds = getSceneContentBounds(targetEl);
  targetEl.classList.remove('is-measuring');

  // PREPARE target entrance state while still hidden
  prepareSceneForEnter(index);

  // Calculate safe zoom and camera target
  var s = scenes[index];
  var preferredZ = s.z;
  var finalZ = calculateSafeFitZoom(bounds.width, bounds.height, preferredZ);
  var camTarget = getSceneCameraTarget(index);

  var settled = false;
  var isEntrancePlayed = false;

  function entranceCallback() {
    if (navId !== navVersion) return;
    if (isEntrancePlayed) return;
    isEntrancePlayed = true;
    if (playEntrance !== false) { triggerSceneEnter(index); }
    else { forceSceneFinalState(index); }
  }

  function completeCallback() {
    if (navId !== navVersion) return;
    if (settled) return;
    settled = true;
    fromEl.classList.remove('is-leaving');
    targetEl.classList.remove('is-entering');
    setActiveScene(index);
    currentScene = index;
    currentNavTimeline = null;
    updateProgress();
  }

  if (playEntrance === false) {
    // Instant/final state — used by audit
    gsap.killTweensOf(camera);
    camera.x = camTarget.x; camera.y = camTarget.y; camera.z = finalZ; camera.r = s.r || 0;
    applyCameraTransform();
    fromEl.classList.remove('is-leaving');
    targetEl.classList.remove('is-entering');
    setActiveScene(index);
    currentScene = index;
    forceSceneFinalState(index);
    updateProgress();
    return;
  }

  var dur = reduceMotion ? 0.001 : (s.d || 1.5);

  // Mark states
  fromEl.classList.add('is-leaving');
  targetEl.classList.add('is-entering');

  currentNavTimeline = gsap.timeline({onComplete: completeCallback});

  // Departure fade: from scene over first 30%
  if (!reduceMotion) {
    currentNavTimeline.to(fromEl, {opacity:0, duration:dur*0.30, ease:'power2.in'}, 0);
  } else {
    gsap.set(fromEl, {opacity:0});
  }

  // Camera movement: full duration
  currentNavTimeline.to(camera, {
    x: camTarget.x, y: camTarget.y, z: finalZ, r: s.r || 0,
    duration: dur, ease: 'power3.inOut',
    onUpdate: applyCameraTransform
  }, 0);

  // Entrance trigger
  var entranceTime = reduceMotion ? 0 : (isImpactScene(index) ? dur : dur * 0.80);
  currentNavTimeline.addLabel('sceneEnter', entranceTime);
  currentNavTimeline.call(entranceCallback, null, 'sceneEnter');
}

function nextScene() { goToScene(currentScene + 1); }
function prevScene() { goToScene(currentScene - 1); }
function firstScene() { goToScene(0); }
function lastScene() { goToScene(scenes.length - 1); }

function updateProgress() {
  if (progressFill) {
    progressFill.style.width = ((currentScene + 1) / scenes.length * 100) + '%';
  }
}

/* ===== SCENE LIFECYCLE ===== */
function triggerSceneEnter(index) {
  var scene = scenes[index];
  var el = document.getElementById('scene-' + scene.id);
  if (!el) return;

  var fnName = 'enter_' + scene.id.replace(/-/g,'_');
  if (typeof window[fnName] === 'function') {
    window[fnName](el);
  } else {
    var children = el.querySelectorAll(':scope > .scene-inner > *');
    gsap.to(children, {opacity:1,y:0,duration:0.5,stagger:0.03,ease:'power2.out',delay:0.1});
  }

  if (particleScenes.indexOf(index) >= 0) { startParticles(); }
  else { stopParticles(); }

  if (index === 18) { startTypewriter(); }

  if (index === 31) {
    var fq = document.getElementById('final-question-text');
    if (fq) { animateWordFade(fq, 350); }
  }

  if (index === 33) {
    var fqEl = document.querySelector('#scene-choose-questions .fq-main');
    if (fqEl) { gsap.fromTo(fqEl, {textShadow:'0 0 0px rgba(255,184,0,0)'}, {textShadow:'0 0 40px rgba(255,184,0,0.3)',duration:1.5,ease:'power2.out'}); }
  }

}


function triggerSceneLeave(index) {
  var scene = scenes[index];
  var el = document.getElementById('scene-' + scene.id);
  if (particleScenes.indexOf(index) >= 0) { stopParticles(); }
  if (index === 21 && connCtx) { connCtx.clearRect(0,0,connCanvas.width,connCanvas.height); connDrawn = false; }
}

var particleScenes = [0, 21];

/* ===== PREPARE SCENE ENTER (set initial states before visibility) ===== */
function resetTypewriter() {
  typewriterDone = false;
  var target = document.getElementById('typewriter-target');
  if (target) target.textContent = '';
}

function prepareSceneForEnter(index) {
  var el = document.getElementById('scene-' + scenes[index].id);
  if (!el) return;

  if (index === 18) { resetTypewriter(); }
  if (index === 21) {
    if (connCtx) { connCtx.clearRect(0,0,connCanvas.width,connCanvas.height); }
    connDrawn = false;
  }

  switch (scenes[index].id) {
    case 'title':
      gsap.set(el.querySelectorAll('.s-line'), {y:30,opacity:0});
      gsap.set(el.querySelector('.s-sub'), {opacity:0});
      break;
    case 'salary':
      gsap.set(el.querySelector('.s-question'), {scale:0.8,opacity:0});
      break;
    case 'value':
      gsap.set(el.querySelector('.quote-card'), {y:20,opacity:0});
      break;
    case 'human-limits':
      gsap.set(el.querySelectorAll('.limit-item'), {scale:0.5,opacity:0});
      break;
    case 'bottleneck':
      gsap.set(el.querySelector('.b-old'), {opacity:0});
      gsap.set(el.querySelectorAll('.b-items span'), {x:-20,opacity:0});
      break;
    case 'asking-judging-acting':
      gsap.set(el.querySelectorAll('.s-statement'), {y:15,opacity:0});
      break;
    case 'worried-overconfident':
      gsap.set(el.querySelector('.split-worried'), {x:-100,opacity:0});
      gsap.set(el.querySelector('.split-over'), {x:100,opacity:0});
      break;
    case 'which-part-cheap':
      gsap.set(el.querySelector('.s-bigquestion'), {scale:0.3,opacity:0});
      break;
    case 'rs-5000': case '7-days': case 'rs-1000':
      gsap.set(el.querySelector('.big-number'), {scale:0.2,opacity:0});
      break;
    case 'challenge-overview':
      gsap.set(el.querySelectorAll('.ct-item'), {scale:0.5,opacity:0});
      gsap.set(el.querySelector('.s-question-sm'), {opacity:0});
      break;
    case 'nouns':
      gsap.set(el.querySelectorAll('.nouns-list span'), {x:-20,opacity:0});
      break;
    case 'questions':
      gsap.set(el.querySelectorAll('.questions-list span'), {x:20,opacity:0});
      break;
    case 'execution-quote':
      gsap.set(el.querySelector('.quote-card'), {scale:0.8,opacity:0});
      break;
    case 'direction-missing':
      gsap.set(el.querySelector('.quote-card'), {y:20,opacity:0});
      break;
    case 'ai-ecosystem':
      gsap.set(el.querySelectorAll('.tool-node'), {scale:0.3,opacity:0});
      gsap.set(el.querySelector('.constellation-center'), {scale:0.94,opacity:0});
      break;
    case 'ten-ten':
      gsap.set(el.querySelectorAll('.ten-number'), {scale:0.2,opacity:0});
      break;
    case 'one-x-ten-thousand':
      gsap.set(el.querySelectorAll('.eq-part'), {scale:0.2,opacity:0});
      gsap.set(el.querySelectorAll('.d-node'), {y:10,opacity:0});
      break;
    case 'without-judgment':
      gsap.set(el.querySelector('.quote-card'), {opacity:0});
      break;
    case 'updates':
      gsap.set(el.querySelectorAll('.update-item'), {y:15,opacity:0});
      break;
    case 'when-updated':
      // Restore original authored HTML for fresh word-fade animation
      var fq = document.getElementById('final-question-text');
      if (fq && originalFinalQuestionHTML) { fq.innerHTML = originalFinalQuestionHTML; }
      break;
    case 'choose-questions':
      gsap.set(el.querySelectorAll('.fq > *'), {y:15,opacity:0});
      gsap.set(el.querySelector('.fq-main'), {scale:0.96,textShadow:'0 0 0px rgba(255,184,0,0)'});
      break;
    case 'thank-you':
      gsap.set(el.querySelector('.thank-you-text'), {scale:0.92,opacity:0});
      break;
    default:
      gsap.set(el.querySelectorAll(':scope > .scene-inner > *'), {y:5,opacity:0});
      break;
  }
}

/* ===== SCENE CONTENT BOUNDS MEASUREMENT ===== */
function getSceneContentBounds(el) {
  var inner = el.querySelector('.scene-inner');
  if (!inner) return {width:600, height:400};

  var elements = [];

  // Scoped: AI ecosystem — measure semantic content only, not constellation border box
  if (el.id === 'scene-ai-ecosystem') {
    var centerEl = el.querySelector('.constellation-center');
    if (centerEl) elements.push(centerEl);
    var toolNodes = el.querySelectorAll('.tool-node');
    toolNodes.forEach(function(n) { elements.push(n); });
  } else {
    // 1. Direct children of .scene-inner (main content blocks)
    var children = inner.children;
    for (var i = 0; i < children.length; i++) {
      elements.push(children[i]);
    }

    // 2. Absolutely positioned .tool-node descendants that may overflow their parent
    var toolNodes = inner.querySelectorAll('.tool-node');
    for (var i = 0; i < toolNodes.length; i++) {
      if (elements.indexOf(toolNodes[i]) === -1) {
        elements.push(toolNodes[i]);
      }
    }
  }

  // 3. Temporarily neutralize GSAP entrance transforms on measured elements
  //    (scale affects getBoundingClientRect dimensions; translate/opacity do not)
  var scaleSaves = [];
  for (var i = 0; i < elements.length; i++) {
    var e = elements[i];
    var s = gsap.getProperty(e, 'scale');
    if (s !== undefined && Math.abs(s - 1) > 0.01) {
      scaleSaves.push({el:e, scale:s});
      gsap.set(e, {scale:1, overwrite:'auto'});
    }
  }

  // 4. Compute union bounding rect
  var minLeft = Infinity, minTop = Infinity;
  var maxRight = -Infinity, maxBottom = -Infinity;

  for (var i = 0; i < elements.length; i++) {
    var child = elements[i];
    var cs = getComputedStyle(child);
    if (cs.display === 'none') continue;
    var rect = child.getBoundingClientRect();
    if (rect.width === 0 && rect.height === 0) continue;
    minLeft = Math.min(minLeft, rect.left);
    minTop = Math.min(minTop, rect.top);
    maxRight = Math.max(maxRight, rect.right);
    maxBottom = Math.max(maxBottom, rect.bottom);
  }

  // 5. Restore GSAP entrance transforms
  for (var i = 0; i < scaleSaves.length; i++) {
    gsap.set(scaleSaves[i].el, {scale:scaleSaves[i].scale, overwrite:'auto'});
  }

  if (minLeft === Infinity) {
    return {width:inner.scrollWidth||600, height:inner.scrollHeight||400};
  }

  // Correct for camera transform (getBoundingClientRect includes camera zoom/translate)
  var currentZoom = camera.z || 1;
  var visualW = (maxRight - minLeft) / currentZoom;
  var visualH = (maxBottom - minTop) / currentZoom;

  return {width:visualW, height:visualH};
}

/* ===== SAFE-FIT ZOOM ===== */
function calculateSafeFitZoom(contentW, contentH, preferredZ) {
  var safeW = window.innerWidth * 0.88;
  var safeH = window.innerHeight * 0.80;
  var fitX = safeW / contentW;
  var fitY = safeH / contentH;
  var safeZ = Math.min(fitX, fitY);
  safeZ = Math.max(0.15, Math.min(2.5, safeZ));
  return Math.min(preferredZ, safeZ);
}

/* ===== FORCE FINAL SCENE STATE (for audit) ===== */
function forceSceneFinalState(index) {
  var el = document.getElementById('scene-' + scenes[index].id);
  if (!el) return;
  gsap.set(el.querySelectorAll('.s-line'),          {y:0,opacity:1});
  gsap.set(el.querySelector('.s-sub'),              {opacity:1});
  gsap.set(el.querySelectorAll('.s-question'),       {scale:1,opacity:1});
  gsap.set(el.querySelectorAll('.quote-card'),       {y:0,scale:1,opacity:1});
  gsap.set(el.querySelectorAll('.limit-item'),       {scale:1,opacity:1});
  gsap.set(el.querySelector('.b-old'),               {opacity:0.5});
  gsap.set(el.querySelectorAll('.b-items span'),     {x:0,opacity:1});
  gsap.set(el.querySelectorAll('.s-statement'),      {y:0,opacity:1});
  gsap.set(el.querySelector('.split-worried'),       {x:0,opacity:1});
  gsap.set(el.querySelector('.split-over'),          {x:0,opacity:1});
  gsap.set(el.querySelector('.s-bigquestion'),       {scale:1,opacity:1});
  gsap.set(el.querySelectorAll('.big-number'),       {scale:1,opacity:1});
  gsap.set(el.querySelectorAll('.ct-item'),          {scale:1,opacity:1});
  gsap.set(el.querySelector('.s-question-sm'),       {opacity:1});
  gsap.set(el.querySelectorAll('.nouns-list span'),  {x:0,opacity:1});
  gsap.set(el.querySelectorAll('.questions-list span'), {x:0,opacity:1});
  gsap.set(el.querySelectorAll('.tool-node'),        {scale:1,opacity:1});
  gsap.set(el.querySelector('.constellation-center'), {scale:1,opacity:1});
  gsap.set(el.querySelectorAll('.ten-number'),       {scale:1,opacity:1});
  gsap.set(el.querySelectorAll('.eq-part'),          {scale:1,opacity:1});
  gsap.set(el.querySelectorAll('.d-node'),           {y:0,opacity:1});
  gsap.set(el.querySelectorAll('.update-item'),      {y:0,opacity:1});
  gsap.set(el.querySelectorAll('.fq > *'),           {y:0,opacity:1});
  gsap.set(el.querySelector('.fq-main'),             {scale:1,textShadow:'0 0 30px rgba(255,184,0,0.2)'});
  gsap.set(el.querySelector('.thank-you-text'),     {scale:1,opacity:1});
