/* ===== WORD-BY-WORD FADE ===== */
function animateWordFade(element, delayPerWord) {
  if (!element) return;
  if (element.dataset.wfDone === '1') return;
  element.dataset.wfDone = '1';

  var delayPerWordMs = delayPerWord || 300;
  var wordIndex = 0;

  function processText(text, target) {
    if (!text) return;
    var parts = text.split(/(\s+)/);
    for (var p = 0; p < parts.length; p++) {
      var part = parts[p];
      if (!part) continue;
      if (part.trim() === '') {
        target.appendChild(document.createTextNode(part));
      } else {
        var idx = wordIndex++;
        var span = document.createElement('span');
        span.textContent = part;
        span.dataset.wf = '1';
        span.style.opacity = '0';
        span.style.transition = 'opacity 0.5s ease ' + (idx * delayPerWordMs) + 'ms';
        target.appendChild(span);
        (function(el, d) {
          setTimeout(function() { el.style.opacity = '1'; }, 100 + d);
        })(span, idx * delayPerWordMs);
      }
    }
  }

  function processNode(node, target) {
    if (node.nodeType === 3) {
      processText(node.textContent, target);
    } else if (node.nodeType === 1) {
      if (node.tagName === 'BR') {
        target.appendChild(document.createElement('br'));
        return;
      }
      var clone = document.createElement(node.tagName);
      for (var a = 0; a < node.attributes.length; a++) {
        clone.setAttribute(node.attributes[a].name, node.attributes[a].value);
      }
      for (var c = 0; c < node.childNodes.length; c++) {
        processNode(node.childNodes[c], clone);
      }
      target.appendChild(clone);
    }
  }

  var fragment = document.createDocumentFragment();
  var childNodes = Array.prototype.slice.call(element.childNodes);
  for (var i = 0; i < childNodes.length; i++) {
    processNode(childNodes[i], fragment);
  }
  element.innerHTML = '';
  element.appendChild(fragment);
}

/* ===== TOOL CONNECTION LINES ===== */
function drawConnections() {
  var container = document.getElementById('constellation');
  if (!container) return;
  connCanvas = document.getElementById('connections-canvas');
  if (!connCanvas) return;
  connCtx = connCanvas.getContext('2d');
  var rect = container.getBoundingClientRect();
  connCanvas.width = container.offsetWidth || 900;
  connCanvas.height = container.offsetHeight || 650;
  if (connDrawn) return;
  connDrawn = true;

  var toolEls = container.querySelectorAll('.tool-node');
  var positions = [];
  var toolColors = {
    'opencode':     {r:34,  g:211, b:238},
    'ollama':       {r:139, g:92,  b:246},
    'n8n':          {r:249, g:115, b:22},
    'crewai':       {r:236, g:72,  b:153},
    'comfyui':      {r:236, g:72,  b:153},
    'browseruse':   {r:34,  g:211, b:238},
    'hyperbrowser': {r:59,  g:130, b:246},
    'openhands':    {r:34,  g:197, b:94},
    'tmux':         {r:255, g:184, b:0},
    'design-tool':  {r:139, g:92,  b:246}
  };
  var canvasRect = connCanvas.getBoundingClientRect();
  var scaleX = connCanvas.width / canvasRect.width;
  var scaleY = connCanvas.height / canvasRect.height;
  toolEls.forEach(function(el) {
    var nodeRect = el.getBoundingClientRect();
    var cssCX = nodeRect.left - canvasRect.left + nodeRect.width / 2;
    var cssCY = nodeRect.top - canvasRect.top + nodeRect.height / 2;
    positions.push({x: cssCX * scaleX, y: cssCY * scaleY});
  });

  var alpha = 0.06;
  function drawLine() {
    if (!connCtx) return;
    connCtx.clearRect(0, 0, connCanvas.width, connCanvas.height);
    for (var i = 0; i < positions.length; i++) {
      for (var j = i + 1; j < positions.length; j++) {
        var dx = positions[i].x - positions[j].x;
        var dy = positions[i].y - positions[j].y;
        var dist = Math.sqrt(dx*dx + dy*dy);
        if (dist < 600) {
          var tool1 = toolEls[i].getAttribute('data-tool');
          var tc = toolColors[tool1] || {r:255,g:184,b:0};
          connCtx.beginPath();
          connCtx.moveTo(positions[i].x, positions[i].y);
          connCtx.lineTo(positions[j].x, positions[j].y);
          connCtx.strokeStyle = 'rgba('+tc.r+','+tc.g+','+tc.b+','+(alpha * (1 - dist/600))+')';
          connCtx.lineWidth = 0.6;
          connCtx.stroke();
        }
      }
    }
    if (alpha < 0.2) {
      alpha += 0.005;
      requestAnimationFrame(drawLine);
    }
  }
  drawLine();
}

/* ===== PARTICLES ===== */
function resizeParticleCanvas() {
  particleCanvas.width = window.innerWidth;
  particleCanvas.height = window.innerHeight;
}
window.addEventListener('resize', resizeParticleCanvas);
resizeParticleCanvas();

function createParticles(count) {
  particles = [];
  for (var i = 0; i < count; i++) {
    particles.push({
      x: Math.random() * particleCanvas.width,
      y: Math.random() * particleCanvas.height,
      vx: (Math.random() - 0.5) * 0.3,
      vy: (Math.random() - 0.5) * 0.3 - 0.1,
      r: Math.random() * 2.5 + 0.5,
      baseOpacity: Math.random() * 0.4 + 0.1,
      life: Math.random() * 120 + 60,
      maxLife: Math.random() * 120 + 60,
      drift: Math.sin(Math.random() * Math.PI * 2) * 0.08
    });
  }
}

function animateParticles() {
  if (!particleActive) {
    pCtx.clearRect(0, 0, particleCanvas.width, particleCanvas.height);
    pRaf = null;
    return;
  }
  pCtx.clearRect(0, 0, particleCanvas.width, particleCanvas.height);
  for (var i = 0; i < particles.length; i++) {
    var p = particles[i];
    p.x += p.vx + Math.sin(p.life * 0.02) * p.drift;
    p.y += p.vy;
    p.life--;
    var opacity = p.baseOpacity * Math.min(1, (p.life / p.maxLife) * 2);
    if (p.life <= 0) {
      p.x = Math.random() * particleCanvas.width;
      p.y = particleCanvas.height + 10;
      p.life = p.maxLife = Math.random() * 120 + 60;
      p.baseOpacity = Math.random() * 0.4 + 0.1;
      p.r = Math.random() * 2.5 + 0.5;
    }
    pCtx.beginPath();
    pCtx.arc(p.x, p.y, p.r, 0, Math.PI * 2);
    pCtx.fillStyle = 'rgba(255, 179, 0, ' + opacity + ')';
    pCtx.fill();
  }
  pRaf = requestAnimationFrame(animateParticles);
}

function startParticles() {
  if (particleActive) return;
  particleActive = true;
  particleCanvas.classList.add('active');
  createParticles(40);
  if (pRaf) cancelAnimationFrame(pRaf);
  animateParticles();
}

function stopParticles() {
  particleActive = false;
  particleCanvas.classList.remove('active');
  if (pRaf) { cancelAnimationFrame(pRaf); pRaf = null; }
  pCtx.clearRect(0, 0, particleCanvas.width, particleCanvas.height);
}

/* ===== OVERVIEW MODE ===== */
function enterOverview() {
  if (currentNavTimeline) { currentNavTimeline.kill(); currentNavTimeline = null; }
  overviewActive = true;
  prevOverviewScene = currentScene;
  // Show all scenes dimmed
  document.querySelectorAll('.scene').forEach(function(el) {
    el.classList.remove('is-active', 'is-entering', 'is-leaving');
    el.style.opacity = '0.18';
    el.style.visibility = 'visible';
    el.style.pointerEvents = 'none';
  });
  var curEl = document.getElementById('scene-' + scenes[currentScene].id);
  if (curEl) curEl.style.opacity = '0.45';
  zoneLabels.classList.add('active');
  hud.classList.add('hud-hidden');
  gsap.to(camera, {
    x: 500, y: -100, z: 0.25, r: 0,
    duration: 1.6, ease: 'power3.inOut',
    onUpdate: applyCameraTransform
  });
}

function exitOverview() {
  if (!overviewActive) return;
  overviewActive = false;
  zoneLabels.classList.remove('active');
  hud.classList.remove('hud-hidden');
  var targetScene = scenes[prevOverviewScene];
  var exitCamTarget = getSceneCameraTarget(prevOverviewScene);
  gsap.to(camera, {
    x: exitCamTarget.x, y: exitCamTarget.y, z: targetScene.z, r: targetScene.r || 0,
    duration: 1.4, ease: 'power3.inOut',
    onUpdate: function() {
      applyCameraTransform();
    },
    onComplete: function() {
      document.querySelectorAll('.scene').forEach(function(el) {
        el.style.opacity = '';
        el.style.visibility = '';
        el.style.pointerEvents = '';
      });
      setActiveScene(prevOverviewScene);
      // Restore the scene's entrance state and replay if needed
      // (scene already has rendered content from being visible in overview)
    }
  });
}

function goToZone(sceneId) {
  var idx = -1;
  for (var i = 0; i < scenes.length; i++) {
    if (scenes[i].id === sceneId) { idx = i; break; }
  }
  if (idx >= 0) {
    overviewActive = false;
    zoneLabels.classList.remove('active');
    hud.classList.remove('hud-hidden');
    goToScene(idx);
  }
}

/* ===== NAVIGATION ===== */
document.addEventListener('keydown', function(e) {
  if (e.key === 'ArrowRight' || e.key === 'ArrowDown' || e.key === ' ') {
    e.preventDefault();
    if (overviewActive) { exitOverview(); return; }
    nextScene();
  }
  if (e.key === 'ArrowLeft' || e.key === 'ArrowUp') {
    e.preventDefault();
    if (overviewActive) { exitOverview(); return; }
    prevScene();
  }
  if (e.key === 'Home') { e.preventDefault(); firstScene(); }
  if (e.key === 'End') { e.preventDefault(); lastScene(); }
  if (e.key === 'o' || e.key === 'O') {
    e.preventDefault();
    if (overviewActive) { exitOverview(); } else { enterOverview(); }
  }
  if (e.key === 'f' || e.key === 'F') {
    e.preventDefault();
    toggleFullscreen();
  }
});

