  content:''; position:absolute; top:0; left:-200%;
  width:200%; height:100%;
  background:linear-gradient(90deg,transparent 0%,rgba(255,215,0,0.7) 30%,var(--gold) 50%,rgba(255,215,0,0.7) 70%,transparent 100%);
