.b-items .b-judge { color:var(--violet); border-left:6px solid var(--violet); box-shadow:0 0 40px rgba(139,92,246,0.1); }
.b-items .b-act { color:var(--green); border-left:6px solid var(--green); box-shadow:0 0 40px rgba(34,197,94,0.1); }

