.constellation { position:relative; width:1600px; height:1100px; margin:0 auto; }
#scene-ai-ecosystem .constellation { margin:0; }
#scene-ai-ecosystem .constellation-center {
  position:absolute; left:50%; top:50%; transform:translate(-50%,-50%);
  z-index:3; display:flex; flex-direction:column; align-items:center; justify-content:center;
  width:min(900px,80%); text-align:center; pointer-events:none;
}
#scene-ai-ecosystem .constellation-center .slide-label { margin-bottom:1.5rem; }
#scene-ai-ecosystem .constellation-center .s-heading { margin:0; max-width:900px; line-height:1.2; }
#scene-ai-ecosystem .constellation-origin { position:absolute; left:50%; top:50%; width:0; height:0; z-index:2; }
