#hud { bottom:3rem; }
.hud-btn { width:50px; height:50px; font-size:1.5rem; }
.hud-btn-sm { width:40px; height:40px; font-size:1.1rem; }
#progress-bar { width:160px; height:3px; }

/* Zone labels */
.zl-item { font-size:1.8rem; font-weight:700; padding:0.8rem 2rem; }

