.b-old { font-size:4rem; font-weight:800; color:var(--text-muted); text-decoration:line-through; opacity:0.4; }
.b-arrow { font-size:2.8rem; color:var(--gold); animation:bounceArrow 2s ease-in-out infinite; }
@keyframes bounceArrow { 0%,100%{transform:translateY(0)}50%{transform:translateY(10px);opacity:0.5} }
.b-now { font-size:1.8rem; color:var(--gold); font-weight:600; }
.b-items { display:flex; gap:2rem; }
.b-items span { font-size:3.5rem; font-weight:800; padding:1rem 2rem; background:var(--surface); border-radius:16px; }
.b-items .b-ask { color:var(--cyan); border-left:6px solid var(--cyan); box-shadow:0 0 40px rgba(34,211,238,0.1); }
.b-items .b-judge { color:var(--violet); border-left:6px solid var(--violet); box-shadow:0 0 40px rgba(139,92,246,0.1); }
.b-items .b-act { color:var(--green); border-left:6px solid var(--green); box-shadow:0 0 40px rgba(34,197,94,0.1); }

/* Split view - keep but refine */
.split-view { display:flex; gap:0; border-radius:20px; overflow:hidden; }
.split-side { flex:1; padding:3rem 2.5rem; display:flex; flex-direction:column; align-items:center; gap:1.5rem; min-width:400px; }
.split-worried { background:linear-gradient(135deg,rgba(239,68,68,0.1) 0%,rgba(17,11,11,0.15) 100%); border-right:1px solid rgba(255,255,255,0.06); }
.split-over { background:linear-gradient(135deg,rgba(34,197,94,0.08) 0%,rgba(11,17,11,0.12) 100%); }
.split-label { font-size:1.5rem; font-weight:800; text-transform:uppercase; letter-spacing:0.1em; }
.split-worried .split-label { color:var(--red); }
.split-over .split-label { color:var(--green); }
.split-person-visual { width:350px; height:280px; border-radius:32px; overflow:hidden; position:relative; isolation:isolate; background:rgba(255,255,255,0.03); flex-shrink:0; }
.split-person-visual img { width:100%; height:100%; display:block; object-fit:cover; }
.split-person-overlay { position:absolute; inset:0; pointer-events:none; background:linear-gradient(180deg,rgba(7,11,23,0.02),rgba(7,11,23,0.5)); }
.split-person-visual.image-failed { background:rgba(255,255,255,0.03); }
.split-person-visual.image-failed img { display:none; }
.split-thought { font-size:1.8rem; color:var(--text-secondary); font-style:italic; max-width:300px; }
.split-tag { font-size:1.2rem; font-weight:600; opacity:0.6; }

/* Tool constellation - keep but enhance */
.constellation { position:relative; width:1600px; height:1100px; margin:0 auto; }
#scene-ai-ecosystem .constellation { margin:0; }
#scene-ai-ecosystem .constellation-center {
  position:absolute; left:50%; top=50%; transform:translate(-50%,-50%);
  z-index:3; display:flex; flex-direction:column; align-items:center; justify-content:center;
  width:min(900px,80%); text-align:center; pointer-events:none;
}
#scene-ai-ecosystem .constellation-center .slide-label { margin-bottom:1.5rem; }
#scene-ai-ecosystem .constellation-center .s-heading { margin:0; max-width:900px; line-height:1.15; }
#scene-ai-ecosystem .constellation-origin { position:absolute; left=50%; top=50%; width=0; height=0; z-index=2; }
#scene-ai-ecosystem #connections-canvas { z-index=0; }
#connections-canvas { position:absolute; inset=0; width=100%; height=100%; pointer-events=none; z-index=0; }
.tool-node {
  position=absolute; display=flex; flex-direction=column; align-items=center; gap=0.6rem;
  cursor=pointer; z-index=2; opacity=0;
  transform=translate(-50%,-50%);
}
.tool-node .tn-icon { width=80px; height=80px; border-radius=16px; display=flex; align-items=center; justify-content=center; border=1px solid rgba(255,255,255,0.12); background=rgba(17,26,46,0.9); }
.tool-node .tn-name { font-size=1.5rem; font-weight=700; color=var(--text-primary); white-space=nowrap; }
.tool-node .tn-cap { font-size=1.15rem; font-weight=500; color=var(--text-secondary); white-space=nowrap; }
.tool-node .tn-icon svg { width=40px; height=40px; }
.tool-node:hover .tn-icon { border-color=var(--gold); box-shadow=0 0 25px rgba(255,184,0,0.15); }

/* 10/10 DISPLAY */
.ten-display { display=flex; align-items=baseline; gap=0.8rem; margin=0.5rem 0; }
.ten-number { font-size=7rem; font-weight=900; color=var(--gold); line-height=1; }
.ten-label { font-size=1.8rem; color=var(--text-muted); font-weight=300; }

/* Final question specific styles */
.final-question { font-size=7.5rem; font-weight=900; color=var(--text-primary); text-align=center; line-height=1.15; max-width=90%; }

/* Update styles */
.update-stack { display=flex; flex-direction=column; gap=1rem; }
.update-item { font-size=3rem; font-weight=500; color=var(--text-secondary); line-height=1.4; }

/* Question card */
.question-card {
  background=linear-gradient(145deg,rgba(23,35,61,0.9),rgba(11,17,33,0.9));
  border-radius=16px;
  padding=2.5rem;
  max-width=90%;
  text-align=left;
}

/* Alert cards for specific emotions */
.alert-warn {
  background=linear-gradient(145deg,rgba(239,68,68,0.08),rgba(17,11,11,0.12));
  border-left=6px solid var(--red);
  border-radius=16px;
  padding=2.5rem;
}
.alert-info {
  background=linear-gradient(145deg,rgba(34,211,238,0.08),rgba(11,17,33,0.12));
  border-left=6px solid var(--cyan);
  border-radius=16px;
  padding=2.5rem;
}
.alert-success {
  background=linear-gradient(145deg,rgba(34,197,94,0.08),rgba(11,17,33,0.12));
  border-left=6px solid var(--green);
  border-radius=16px;
  padding=2.5rem;
}

/* Text color utilities */
.text-gold { color:var(--gold) !important; }
.text-cyan { color:var(--cyan) !important; }
.text-violet { color:var(--violet) !important; }
.text-blue { color:var(--blue) !important; }
.text-pink { color:var(--pink) !important; }
.text-green { color:var(--green) !important; }
.text-orange { color:var(--orange) !important; }
.text-red { color:var(--red) !important; }
.text-primary { color=var(--text-primary) !important; }
.text-secondary { color=var(--text-secondary) !important; }
.text-muted { color=var(--text-muted) !important; }

/* Gradient text */
.gradient-gold {
  background:linear-gradient(135deg,var(--gold),var(--gold-bright),var(--orange));
  -webkit-background-clip:text; background-clip:text; color:transparent;
}
.gradient-white-gold {
  background:linear-gradient(135deg,#FFF,var(--gold));
  -webkit-background-clip:text; background-clip:text; color:var(--gold);
}
.gradient-cyan-violet {
  background:linear-gradient(135deg,var(--cyan),var(--violet));
  -webkit-background-clip:text; background-clip:text; color:transparent;
}
.gradient-violet-pink {
  background:linear-gradient(135deg,var(--violet),var(--pink));
  -webkit-background-clip:text; background-clip:text; color:transparent;
}
.gradient-red-orange {
  background:linear-gradient(135deg,var(--red),var(--orange));
  -webkit-background-clip:text; background-clip:text; color:transparent;
}

/* Scene typography */
.slide-label {
  font-size=1.1rem; font-weight=600; text-transform=uppercase;
  letter-spacing=0.15em; color=var(--accent); margin-bottom=1rem;
}
.s-title { font-size=7rem!important; font-weight=900!important; text-align=center; line-height=1.15; }
.s-line { display=inline-block; }
.s-question { font-size=4.5rem; font-weight=700; text-align=center; max-width=90%; }
.s-question-sm { font-size=2.8rem; font-weight=600; text-align=center; }
.s-prompt { font-size=1.8rem; color=var(--text-secondary); margin-bottom=0.8rem; }
.s-footnote { font-size=1.15rem; margin-top=0.8rem; color=var(--text-muted); }
.s-heading { font-size=3rem; text-align=center; margin-bottom=1.5rem; }
.s-statement { font-size=2.5rem; font-weight=300; color=var(--text-secondary); max-width=90%; }
.s-bigquestion { font-size=5.5rem; font-weight=900; text-align=center; max-width=90%; line-height=1.2; }
.s-strikethrough { font-size=2rem; color=var(--text-muted); text-decoration=line-through; margin-bottom=1.8rem; }
.s-faded { font-size=2rem; color=var(--text-secondary); font-weight=300; max-width=80%; }
.s-answer { font-size=2.8rem; font-weight=700; margin-top=0.8rem; }
.s-sub { font-size=1.6rem; color=var(--text-secondary); }

/* Gold line / divider */
.gold-line {
  width=80px; height=4px;
  background=var(--gold); border-radius=2px;
  margin=1.5rem 0; position=relative; overflow=hidden;
}
.gold-line::after {
  content=''; position=absolute; top=0; left=-200%;
  width=200%; height=100%;
  background=linear-gradient(90deg,transparent 0%,#FFD700 30%,#FFB800 50%,#FFD700 70%,transparent 100%);
  animation=goldSweep 2.5s ease-in-out infinite;
}
.gold-line.cyan { background=var(--cyan); }
.gold-line.violet { background=var(--violet); }
.gold-line.green { background=var(--green); }
.gold-line.red { background=var(--red); }
.gold-line.orange { background=var(--orange); }
.gold-line.cyan::after,
.gold-line.violet::after,
.gold-line.green::after,
.gold-line.red::after,
.gold-line.orange::after { background=none; }
@keyframes goldSweep { 0%{left:-200%}100%{left:200%} }

/* Legacy card variants - keep for backward compatibility during transition */
.card-base {
  background=linear-gradient(145deg,rgba(23,35,61,0.96),rgba(11,17,33,0.96));
  border-radius=16px; padding=2.5rem; position=relative;
  max-width=90%;
}
.card-gold {
  border=1px solid rgba(255,184,0,0.35);
  box-shadow=0 20px 60px rgba(0,0,0,0.35), 0 0 40px rgba(255,184,0,0.10);
}
.card-cyan {
  border=1px solid rgba(34,211,238,0.35);
  box-shadow=0 20px 60px rgba(0,0,0,0.35), 0 0 40px rgba(34,211,238,0.10);
}
.card-violet {
  border=1px solid rgba(139,92,246,0.35);
  box-shadow=0 20px 60px rgba(0,0,0,0.35), 0 0 40px rgba(139,92,246,0.10);
}
.card-green {
  border=1px solid rgba(34,197,94,0.35);
  box-shadow=0 20px 60px rgba(0,0,0,0.35), 0 0 40px rgba(34,197,94,0.10);
}
.card-red {
  border=1px solid rgba(239,68,68,0.35);
  box-shadow=0 20px 60px rgba(0,0,0,0.35), 0 0 40px rgba(239,68,68,0.10);
}
.card-orange {
  border=1px solid rgba(249,115,22,0.35);
  box-shadow=0 20px 60px rgba(0,0,0,0.35), 0 0 40px rgba(249,115,22,0.10);
}

/* Quote card (legacy - now uses card-base + variant) */
.quote-card {
  background=linear-gradient(145deg,rgba(23,35,61,0.96),rgba(11,17,33,0.96));
  border-left=6px solid var(--gold);
  border-radius=16px;
  padding=2.5rem;
  max-width=90%;
  box-shadow=0 20px 60px rgba(0,0,0,0.35), 0 0 35px rgba(255,184,0,0.10);
}
.quote-card .q-sub { font-size=2rem; font-weight=300; color=var(--text-secondary); margin-bottom=0.5rem; }
.quote-card .q-main { font-size=3rem; font-weight=700; color=var(--text-primary); line-height=1.3; }
.quote-card .q-attribution { font-size=1.3rem; color=var(--text-muted); margin-top=1rem; font-weight=300; }
.quote-card.card-cyan { border-left-color=var(--cyan); }
.quote-card.card-violet { border-left-color=var(--violet); }
.quote-card.card-red { border-left-color=var(--red); }
.quote-card.card-orange { border-left-color=var(--orange); }
.quote-card.card-green { border-left-color=var(--green); }

/* Big number */
.big-number { font-size=9rem; font-weight=900; color=var(--gold); line-height=1; letter-spacing=-0.04em; }
.big-number-sm { font-size=6rem; font-weight=900; color=var(--gold); line-height=1; }

/* Prompt cards */
.prompt-card { background=linear-gradient(145deg,rgba(23,35,61,0.96),rgba(11,17,33,0.96)); border-radius=14px; padding=2rem; min-width=520px; max-width=700px; }
.prompt-generic { border=1px solid rgba(148,163,184,0.2); }
.prompt-contextual { border=1px solid rgba(34,211,238,0.4); box-shadow=0 0 30px rgba(34,211,238,0.08); }
.prompt-label { font-size=0.85rem; font-weight=700; text-transform=uppercase; letter-spacing=0.12em; margin-bottom=1rem; }
.prompt-label.generic { color=var(--text-muted); }
.prompt-label.contextual { color=var(--cyan); }
.prompt-text { font-size=1.4rem; color=var(--text-secondary); font-weight=300; line-height=1.6; font-style=italic; }
.prompt-result { font-size=1.15rem; margin-top=1rem; padding=0.8rem 1rem; border-radius=8px; }
.prompt-generic .prompt-result { background=rgba(255,255,255,0.03); }
.prompt-contextual .prompt-result { background=rgba(34,211,238,0.06); border-left=3px solid var(--cyan); }

/* Spotlight cards */
.spotlight-card { background=linear-gradient(145deg,rgba(23,35,61,0.96),rgba(11,17,33,0.96)); border-radius=16px; padding=2.5rem; text-align=center; min-width=600px; border=1px solid rgba(255,255,255,0.08); }
.spotlight-card .sp-tag { font-size=0.9rem; font-weight=600; text-transform=uppercase; letter-spacing=0.1em; padding=0.4rem 1rem; border-radius=100px; display=inline-block; margin-bottom=1rem; }
.spotlight-card h3 { font-size=2.5rem; font-weight=700; margin-bottom=0.8rem; }
.spotlight-card p { font-size=1.5rem; color=var(--text-secondary); font-weight=300; line-height=1.5; }
.sp-design .sp-tag { color=var(--violet); background=rgba(139,92,246,0.12); }
.sp-code .sp-tag { color=var(--cyan); background=rgba(34,211,238,0.12); }
.sp-multi .sp-tag { color=var(--gold); background=rgba(255,184,0,0.12); }

/* Challenge triangle */
.challenge-triangle { display=grid; grid-template-columns=1fr 1fr; gap=2rem; align-items=center; }
.ct-item { text-align=center; padding=1.2rem 2rem; border-radius=14px; background=linear-gradient(145deg,rgba(23,35,61,0.96),rgba(11,17,33,0.96)); }
.ct-item p { font-size=1.15rem; color=var(--text-muted); margin-top=0.3rem; }
.ct-top { grid-column=1/-1; }
.ct-gold { border=1px solid rgba(255,184,0,0.35); box-shadow=0 0 20px rgba(255,184,0,0.08); }
.ct-cyan { border=1px solid rgba(34,211,238,0.35); box-shadow=0 0 20px rgba(34,211,238,0.08); }
.ct-green { border=1px solid rgba(34,197,94,0.35); box-shadow=0 0 20px rgba(34,197,94,0.08); }
.ct-gold .big-number-sm { color=var(--gold); }
.ct-cyan .big-number-sm { color=var(--cyan); }
.ct-green .big-number-sm { color=var(--green); }

/* Noun list */
.nouns-list { display=flex; flex-direction=column; gap=0.5rem; }
.nouns-list span { font-size=2.8rem; font-weight=300; color=#64758B; }

/* Question list */
.questions-list { display=flex; flex-direction=column; gap=0.8rem; }
.questions-list span { font-size=1.8rem; font-weight=400; padding=0.3rem 0; line-height=1.4; }

/* Equation display (danger) */
.equation-display { display=flex; align-items=center; gap=1rem; justify-content=center; }
.eq-part { font-size=9rem; font-weight=900; letter-spacing=-0.04em; line-height=1; }
.eq-one { color=var(--text-primary); }
.eq-op { font-size=5rem; color=var(--red); opacity=0.5; }
.eq-tenk { color=var(--red); text-shadow=0 0 40px rgba(239,68,68,0.3); }
.eq-caption { font-size=1.6rem; color=var(--text-muted); font-weight=300; margin-top=1rem; }
.danger-grid { display=flex; flex-wrap=wrap; gap=1.2rem; justify-content=center; margin-top=1.5rem; width=100%; }
.d-node { display=flex; align-items=center; gap=0.8rem; padding=0.8rem 1.5rem; border-radius=10px; font-size=1.4rem; color=var(--text-secondary); background=linear-gradient(145deg,rgba(23,35,61,0.96),rgba(11,17,33,0.96)); }
.d-node .d-icon { display=inline-flex; align-items=center; justify-content=center; width=24px; height=24px; height=24px; }
.d-node .d-icon svg { width=18px; height=18px; }
.d-node.d-hallucination { border=1px solid rgba(239,68,68,0.35); }
.d-node.d-security { border=1px solid rgba(249,115,22,0.35); }
.d-node.d-scaling { border=1px solid rgba(239,68,68,0.35); }
.d-node.d-confidence { border=1px solid rgba(249,115,22,0.35); }

/* Final block */
.final-block p { font-size=2rem; color=var(--text-secondary); font-weight=300; line-height=1.5; max-width=85%; margin=0 auto 1.2rem; }
.final-block .fq { font-size=2.8rem; }
.final-block .fq-main { font-size=4.5rem; font-weight=700; }

/* Thank you */
.thank-you-text { font-size=6rem; font-weight=700; color=var(--gold); text-align=center; text-shadow=0 0 30px rgba(255,184,0,0.15); }

/* Ambient glows */
.ambient-glow {
  position=absolute;
  pointer-events=none;
  z-index=1;
  border-radius=50%;
  transform=translate(-50%,-50%);
  filter=blur(120px);
}
.glow-gold   { width=2400px; height=2400px; background=radial-gradient(ellipse,rgba(255,184,0,0.10),transparent 60%); }
.glow-cyan   { width=2200px; height=2200px; background=radial-gradient(ellipse,rgba(34,211,238,0.08),transparent 60%); }
.glow-violet { width=2200px; height=2200px; background=radial-gradient(ellipse,rgba(139,92,246,0.08),transparent 60%); }
.glow-blue   { width=2400px; height=2400px; background=radial-gradient(ellipse,rgba(59,130,246,0.08),transparent 60%); }
.glow-green  { width=2000px; height=2000px; background=radial-gradient(ellipse,rgba(34,197,94,0.07),transparent 60%); }
.glow-red    { width=2200px; height=2200px; background=radial-gradient(ellipse,rgba(239,68,68,0.08),transparent 60%); }
.glow-orange { width=2200px; height=2200px; background=radial-gradient(ellipse,rgba(249,115,22,0.08),transparent 60%); }

/* Parallax */
#parallax-back {
  background=radial-gradient(ellipse 60% 50% at 20% 30%,rgba(7,11,23,0.7),transparent),radial-gradient(ellipse 40% 40% at 80% 70%,rgba(17,26,46,0.3),transparent);
  opacity=0.7;
}
#parallax-mid {
  background=radial-gradient(ellipse 50% 30% at 50% 20%,rgba(255,184,0,0.02),transparent),radial-gradient(ellipse 30% 40% at 70% 80%,rgba(34,211,238,0.02),transparent);
  opacity=0.4;
}

/* HUD */
#hud {
  position=fixed; bottom=2rem; left=50%; transform=translateX(-50%);
  display=flex; align-items=center; gap=1rem;
  z-index=1000;
  opacity=1;
  transition=opacity 0.5s ease;
}
#hud.hud-hidden { opacity=0.15; }
#hud.hud-hidden:hover { opacity=1; }
.hud-btn {
  background=rgba(17,26,46,0.85); border=1px solid rgba(255,255,255,0.08);
  color=var(--gold); font-size=1.2rem;
  width=40px; height=40px; border-radius=50%;
  cursor=pointer; display=flex; align-items=center; justify-content=center;
  transition=background 0.2s; font-family=inherit;
}
.hud-btn:hover { background=rgba(255,184,0,0.12); }
.hud-btn-sm { width=32px; height=32px; font-size=0.9rem; }
#progress-bar { width=120px; height=2px; background=rgba(255,255,255,0.06); border-radius=2px; overflow=hidden; }
#progress-fill { height=100%; width=0%; background=var(--gold); transition=width 0.4s ease; }

/* Zone labels */
#zone-labels {
  position=fixed; inset=0;
  display=flex; flex-wrap=wrap; align-items=center; justify-content=center;
  gap=3rem;
  pointer-events=none;
  z-index=500;
  opacity=0;
  transition=opacity 0.6s ease;
}
#zone-labels.active { opacity=1; pointer-events=auto; }
.zl-item {
  font-size=1.4rem; font-weight=700; color=var(--text-muted);
  text-transform=uppercase; letter-spacing=0.08em;
  cursor=pointer; padding=0.5rem 1.5rem; border=1px solid rgba(255,255,255,0.06);
  border-radius=8px; transition=all 0.3s; background=rgba(7,11,23,0.85);
}
.zl-item:hover { color=var(--gold); border-color=var(--gold); background=rgba(255,184,0,0.06); }

/* Particles */
#particle-canvas { position=fixed; inset=0; width=100%; height=100%; pointer-events=none; z-index=999; opacity=0; transition=opacity 0.8s ease; }
#particle-canvas.active { opacity=1; }

/* Keyframes */
@keyframes elasticBounce {
  0%{transform:scale(0.2);opacity=0}
  50%{transform:scale(1.12)}
  70%{transform:scale(0.9)}
  85%{transform:scale(1.05)}
  100%{transform:scale(1);opacity=1}
}
.elastic-bounce { animation:elasticBounce 1.2s cubic-bezier(0.68,-0.55,0.27,1.55) forwards; }
@keywords fadeUp {
  from{opacity:0;transform:translateY(20px)}
  to{opacity:1;transform:translateY(0)}
}
.fade-up { animation:fadeUp 0.7s ease forwards; }
@keyframes slideInLeft {
  from{transform:translateX(-100%);opacity=0}
  to{transform:translateX(0);opacity=1}
}
@keyframes slideInRight {
  from{transform:translateX(-100%);opacity=0}
  to{transform:translateX(0);opacity=1}
}
@keyframes pulseGlow {
  0%,100%{text-shadow:0 0 20px rgba(255,184,0,0.3),0 0 40px rgba(255,184,0,0.1)}
  50%{text-shadow:0 0 40px rgba(255,184,0,0.5),0 0 80px rgba(255,184,0,0.2)}
}
.word-fade span { display=inline-block; opacity=0; transition=opacity 0.4s ease; }

/* Additional animations for new design */
@keyframes pulse {
  0%, 100% { opacity: 0.3; }
  50% { opacity: 0.7; }
}
@keyframes clockHand {
  0% { transform: translate(-50%, -50%) rotate(0deg); }
  100% { transform: translate(-50%, -50%) rotate(360deg); }
}
@keyframes wrongQuestion {
  0% { left: -100%; }
  100% { left: 100%; }
}
@keyframes collapse {
  0%, 100% { opacity: 0.2; }
  50% { opacity: 0.8; }
}
@keyframes multiply {
  0% { width: 2px; }
  50% { width: 200px; }
  100% { width: 2px; }
}
@keyframes updatePulse {
  0%, 100% { transform: scale(0.8); opacity: 0.6; }
  50% { transform: scale(1.2); opacity: 1; }
}
@keyframes float {
  0% { transform: translateY(0px) rotate(0deg); }
  25% { transform: translateY(-20px) rotate(90deg); }
  50% { transform: translateY(0px) rotate(180deg); }
  75% { transform: translateY(20px) rotate(270deg); }
  100% { transform: translateY(0px) rotate(360deg); }
}

/* Responsive */
@media (max-width:1024px) {
  .scene-inner { min-width=380px; max-width=600px; padding=1.5rem; }
  h1,.s-title { font-size=4rem!important; }
  .s-question { font-size=2.8rem; }
  .s-bigquestion { font-size=3rem; }
  .big-number { font-size=5rem; }
  .big-number-sm { font-size=3.5rem; }
  .s-heading { font-size=2.2rem; }
  .s-statement { font-size=1.8rem; }
  .s-question-sm { font-size=2rem; }
  .final-question { font-size=4.5rem; }
  .final-block .fq-main { font-size=3rem; }
  .thank-you-text { font-size=4rem; }
  .quote-card .q-main { font-size=2.2rem; }
  .limits-grid { flex-wrap=wrap; justify-content=center; }
  .limits-grid .limit-item { flex-basis=40%; }
  .b-items { flex-direction=column; align-items=center; }
  .b-items span { font-size=2rem; }
  .constellation { width=700px; height=600px; }
  .tool-node .tn-icon { width=56px; height=56px; }
  .tool-node .tn-icon svg { width=28px; height=28px; }
  .tool-node .tn-name { font-size=1.1rem; }
  .tool-node .tn-cap { font-size=0.85rem; }
  .ten-number { font-size=4.5rem; }
  .eq-part { font-size=5rem; }
  .split-view { flex-direction=column; }
  .split-side { min-width=auto; }
  .nouns-list span { font-size=2rem; }
  .questions-list span { font-size=1.3rem; }
  .prompt-card { min-width=360px; max-width=500px; }
  .spotlight-card { min-width=400px; }
  .d-node { font-size=1.1rem; }
  .update-item { font-size=2rem; }
  .eq-part { font-size=6rem; }
}
@media (max-width:768px) {
  .scene-inner { min-width=260px; max-width=420px; padding=1.2rem; }
  h1,.s-title { font-size=2.8rem!important; }
  .s-question { font-size=2rem; }
  .s-bigquestion { font-size=2.2rem; }
  .big-number { font-size=3.5rem; }
  .constellation { width=360px; height=380px; }
  .tool-node .tn-icon { width=40px; height=40px; }
  .tool-node .tn-icon svg { width=20px; height=20px; }
  .tool-node .tn-name { font-size=0.8rem; }
  .tool-node .tn-cap { display=none; }
  .update-item { font-size=1.6rem; }
  .final-question { font-size=3rem; }
  .final-block .fq-main { font-size=2.2rem; }
  .thank-you-text { font-size=3rem; }
  .ten-number { font-size=3rem; }
  .eq-part { font-size=3.5rem; }
  .prompt-card { min-width=220px; max-width=360px; }
  .spotlight-card { min-width=240px; }
  #hud { bottom=1rem; gap=0.6rem; }
  #progress-bar { width=60px; }
  .zl-item { font-size=0.9rem; padding=0.3rem 1rem; }
  .d-node { font-size=0.9rem; }
  .limit-visual { width=120px; height=120px; }
}
@media (prefers-reduced-motion:reduce) {
  *,*::before,*::after { animation-duration:0.01ms!important; transition-duration:0.01ms!important; }
  .gold-line::after { animation:none; background=var(--gold); }
  .b-arrow { animation:none; }
}

/* Hide legacy styles that are no longer needed */
.quote-card { display:none; }
.card-base { display:none; }
.card-gold { display:none; }
.card-cyan { display:none; }
.card-violet { display:none; }
.card-green { display:none; }
.card-red { display:none; }
.card-orange { display:none; }
.spotlight-card { display:none; }

toolUseResult.content:
:root {
  --bg: #070B17;
  --deep-navy: #0B1121;
  --surface: #111A2E;
  --surface-elevated: #17233D;
  --gold: #FFB800;
  --gold-bright: #FFD54A;
  --cyan: #22D3EE;
  --cyan-bright: #67E8F9;
  --blue: #3B82F6;
  --blue-bright: #60A5FA;
  --violet: #8B5CF6;
  --violet-bright: #A78BFA;
  --pink: #EC4899;
  --pink-bright: #F472B6;
  --green: #22C55E;
  --green-bright: #4ADE80;
  --orange: #F97316;
  --orange-bright: #FB923C;
  --red: #EF4444;
  --red-bright: #F87171;
  --text-primary: #FFFFFF;
  --text-secondary: #D5DEEB;
  --text-muted: #94A3B8;
  --accent: var(--gold);

  /* Chapter backgrounds */
  --chapter1-bg: radial-gradient(ellipse at bottom, #1A0F0C 0%, #070B17 70%);
  --chapter2-bg: radial-gradient(ellipse at top, #1A0F0C 0%, #0F1A1A 50%, #070B17 100%);
  --chapter3-bg: radial-gradient(ellipse at center, #0F1A1A 0%, #1A0F0C 30%, #070B17 70%);
  --chapter4-bg: radial-gradient(ellipse at top, #0A1A1A 0%, #0F1A2A 50%, #070B17 80%);
  --chapter5-bg: radial-gradient(ellipse at center, #0A1A2A 0%, #0F0A1A 50%, #070B17 80%);
  --chapter6-bg: radial-gradient(ellipse at bottom, #1A0F0F 0%, #0F1A0A 50%, #070B17 80%);
  --chapter7-bg: radial-gradient(ellipse at center, #070B17 0%, #0A0A0A 70%, #000000 90%);
}

* { margin:0; padding:0; box-sizing:border-box; }
html, body { width:100%; height:100%; overflow:hidden; background:var(--bg);

/* NEW TYPOGRAPHY SYSTEM */
font-family: 'Space Grotesk', -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, Oxygen, Ubuntu, Cantarell, 'Open Sans', 'Helvetica Neue', sans-serif;
color:var(--text-primary);
-webkit-font-smoothing:antialiased;
}

#viewport { position:fixed; inset:0; overflow:hidden; perspective:1200px; background:var(--bg); }

#world {
  position:absolute;
  top:0; left:0;
  width:1px; height:1px;
  transform-origin:0 0;
  will-change:transform;
  backface-visibility:hidden;
}

.parallax-layer {
  position:fixed;
  inset:0;
  pointer-events:none;
  z-index:0;
  will-change:transform;
}

/* === SCENE BASE - REDESIGNED === */
.scene {
  position:absolute;
  transform:translate(-50%,-50%);
  z-index:10;
  visibility:hidden;
  pointer-events:none;
}
.scene.is-active { visibility:visible; pointer-events:auto; }
.scene.is-entering { visibility:visible; pointer-events:none; }
.scene.is-leaving { visibility:visible; pointer-events:none; }
.scene.is-measuring { visibility:hidden; pointer-events:none; }

/* Remove default centered column layout - scenes will define their own layout */
.scene-inner {
  position:relative;
  width:100%;
  max-width:none;
  padding:0;
  display:flex;
  flex-direction:column;
  align-items:flex-start;
  min-height:0;
}

/* === NEW TYPOGRAPHY SYSTEM === */
/* Space Grotesk for monumental text */
h1, h2, h3, .s-title, .s-question, .s-bigquestion, .s-statement, .s-answer,
.s-line, .big-number, .ten-number, .eq-part, .final-question, .fq-main {
  font-family: 'Space Grotesk', sans-serif;
  text-transform:none;
  letter-spacing:-0.02em;
}

/* DM Sans for supporting text */
p, .s-prompt, .s-footnote, .s-sub, .slide-label, .limit-label, .limit-sub,
.split-label, .split-thought, .prompt-text, .prompt-result, .tool-node .tn-name,
.tool-node .tn-cap, .update-item, .q-sub, .q-main, .q-attribution, .ten-label,
.d-node, .zl-item, .thank-you-text {
  font-family: 'DM Sans', -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, Oxygen, Ubuntu, Cantarell, 'Open Sans', 'Helvetica Neue', sans-serif;
}

/* Heading sizes - much larger for 75" screen */
h1 { font-size:8rem; font-weight:900; }
h2 { font-size:6rem; font-weight:800; }
h3 { font-size:3.5rem; font-weight:700; }
.s-title { font-size:9rem!important; font-weight:900!important; }
.s-question { font-size:5rem; font-weight:800; max-width:none; }
.s-bigquestion { font-size:7rem; font-weight:900; }
.s-statement { font-size:2.5rem; font-weight:400; }
.s-answer { font-size:3.5rem; font-weight:800; }
.big-number { font-size:12rem; font-weight:900; }
.ten-number { font-size:10rem; font-weight:900; }
.eq-part { font-size:12rem; font-weight:900; }
.final-question { font-size:10rem; font-weight:900; }
.fq-main { font-size:6rem; font-weight:800; }

p { font-size:2rem; font-weight:400; line-height:1.6; }
.s-prompt { font-size:2rem; }
.s-footnote { font-size:1.5rem; }
.subtitle { font-size:1.8rem; }

.limit-label { font-size:2.2rem; font-weight:700; }
.limit-sub { font-size:1.6rem; }

.split-label { font-size:1.8rem; font-weight:700; }
.split-thought { font-size:2rem; font-weight:400; font-style:italic; }

.prompt-text { font-size:2rem; font-weight:400; line-height:1.7; }
.prompt-result { font-size:1.8rem; }

.tool-node .tn-name { font-size:2rem; font-weight:700; }
.tool-node .tn-cap { font-size:1.6rem; font-weight:500; }

.q-main { font-size:4rem; font-weight:800; }
.q-sub, .q-attribution { font-size:1.8rem; font-weight:400; }

.zl-item { font-size:2rem; font-weight:700; }
.thank-you-text { font-size:8rem; font-weight:800; }

/* Updated gold line */
.gold-line {
  width:120px; height:6px;
  background:var(--gold); border-radius:3px;
  margin:2rem 0; position:relative; overflow:hidden;
}
.gold-line::after {
  content:''; position:absolute; top:0; left:-200%;
  width:200%; height:100%;
  background:linear-gradient(90deg,transparent 0%,rgba(255,215,0,0.7) 30%,var(--gold) 50%,rgba(255,215,0,0.7) 70%,transparent 100%);
  animation:goldSweep 3s ease-in-out infinite;
}
.gold-line.cyan { background:var(--cyan); }
.gold-line.violet { background:var(--violet); }
.gold-line.green { background:var(--green); }
.gold-line.red { background:var(--red); }
.gold-line.orange { background:var(--orange); }
.gold-line.cyan::after,
.gold-line.violet::after,
.gold-line.green::after,
.gold-line.red::after,
.gold-line.orange::after { background:none; }
@keyframes goldSweep { 0%{left:-200%}100%{left:200%} }

/* REMOVE GENERIC CARD STYLES - scenes will use specific containers when needed */
/* Keep only essential layout helpers */

/* Limit visual - keep but refine */
.limits-grid { display:flex; gap:3rem; margin-top:2rem; }
.limit-item { display:flex; flex-direction:column; align-items:center; gap:1.5rem; }
.limit-visual { width:220px; height:220px; border-radius:28px; overflow:hidden; position:relative; isolation:isolate; background:rgba(255,255,255,0.03); }
.limit-visual img { width:100%; height:100%; display:block; object-fit:cover; }
.limit-image-overlay { position:absolute; inset:0; pointer-events:none; background:linear-gradient(180deg,rgba(7,11,23,0.02),rgba(7,11,23,0.65)); }
.limit-visual.is-limited::after { content:''; position:absolute; inset:0; pointer-events:none; background:linear-gradient(135deg,transparent 48%,rgba(239,68,68,0.3) 49%,rgba(239,68,68,0.3) 51%,transparent 52%); }
.limit-visual.is-open { box-shadow:inset 0 0 40px rgba(34,211,238,0.1); }
.limit-visual.image-failed { background:rgba(255,255,255,0.03); box-shadow:inset 0 0 25px rgba(255,255,255,0.05); }
.limit-visual.image-failed img { display:none; }

/* Bottleneck - keep but refine */
.bottleneck-visual { display:flex; flex-direction:column; align-items:center; gap:1.5rem; }
.b-old { font-size:4rem; font-weight:800; color:var(--text-muted); text-decoration:line-through; opacity:0.4; }
.b-arrow { font-size:2.8rem; color:var(--gold); animation:bounceArrow 2s ease-in-out infinite; }
@keyframes bounceArrow { 0%,100%{transform:translateY(0)}50%{transform:translateY(10px);opacity:0.5} }
.b-now { font-size:1.8rem; color:var(--gold); font-weight:600; }
.b-items { display:flex; gap:2rem; }
.b-items span { font-size:3.5rem; font-weight:800; padding:1rem 2rem; background:var(--surface); border-radius:16px; }
.b-items .b-ask { color:var(--cyan); border-left:6px solid var(--cyan); box-shadow:0 0 40px rgba(34,211,238,0.1); }
.b-items .b-judge { color:var(--violet); border-left:6px solid var(--violet); box-shadow:0 0 40px rgba(139,92,246,0.1); }
.b-items .b-act { color:var(--green); border-left:6px solid var(--green); box-shadow:0 0 40px rgba(34,197,94,0.1); }

/* Split view - keep but refine */
.split-view { display:flex; gap:0; border-radius:20px; overflow:hidden; }
.split-side { flex:1; padding:3rem 2.5rem; display:flex; flex-direction:column; align-items:center; gap:1.5rem; min-width:400px; }
.split-worried { background:linear-gradient(135deg,rgba(239,68,68,0.1) 0%,rgba(17,11,11,0.15) 100%); border-right:1px solid rgba(255,255,255,0.06); }
.split-over { background:linear-gradient(135deg,rgba(34,197,94,0.08) 0%,rgba(11,17,11,0.12) 100%); }
.split-label { font-size:1.5rem; font-weight:800; text-transform:uppercase; letter-spacing:0.1em; }
.split-worried .split-label { color:var(--red); }
.split-over .split-label { color:var(--green); }
.split-person-visual { width:350px; height:280px; border-radius:32px; overflow:hidden; position:relative; isolation:isolate; background:rgba(255,255,255,0.03); flex-shrink:0; }
.split-person-visual img { width:100%; height:100%; display:block; object-fit:cover; }
.split-person-overlay { position:absolute; inset:0; pointer-events:none; background:linear-gradient(180deg,rgba(7,11,23,0.02),rgba(7,11,23,0.5)); }
.split-person-visual.image-failed { background:rgba(255,255,255,0.03); }
.split-person-visual.image-failed img { display:none; }
.split-thought { font-size:1.8rem; color:var(--text-secondary); font-style:italic; max-width:300px; }
.split-tag { font-size:1.2rem; font-weight:600; opacity:0.6; }

/* Tool constellation - keep but enhance */
.constellation { position:relative; width:1600px; height:1100px; margin:0 auto; }
#scene-ai-ecosystem .constellation { margin:0; }
#scene-ai-ecosystem .constellation-center {
  position:absolute; left:50%; top=50%; transform:translate(-50%,-50%);
  z-index:3; display:flex; flex-direction:column; align-items:center; justify-content:center;
  width:min(900px,80%); text-align:center; pointer-events:none;
}
#scene-ai-ecosystem .constellation-center .slide-label { margin-bottom:1.5rem; }
#scene-ai-ecosystem .constellation-center .s-heading { margin:0; max-width:900px; line-height:1.15; }
#scene-ai-ecosystem .constellation-origin { position:absolute; left=50%; top=50%; width=0; height=0; z-index=2; }
#scene-ai-ecosystem #connections-canvas { z-index=0; }
#connections-canvas { position:absolute; inset=0; width=100%; height=100%; pointer-events=none; z-index=0; }
.tool-node {
  position=absolute; display=flex; flex-direction=column; align-items=center; gap=0.6rem;
  cursor=pointer; z-index=2; opacity=0;
  transform=translate(-50%,-50%);
}
.tool-node .tn-icon { width=80px; height=80px; border-radius=16px; display=flex; align-items=center; justify-content=center; border=1px solid rgba(255,255,255,0.12); background=rgba(17,26,46,0.9); }
.tool-node .tn-name { font-size=1.5rem; font-weight=700; color=var(--text-primary); white-space=nowrap; }
.tool-node .tn-cap { font-size=1.15rem; font-weight=500; color=var(--text-secondary); white-space=nowrap; }
.tool-node .tn-icon svg { width=40px; height=40px; }
.tool-node:hover .tn-icon { border-color=var(--gold); box-shadow=0 0 25px rgba(255,184,0,0.15); }

/* 10/10 DISPLAY */
.ten-display { display=flex; align-items=baseline; gap=0.8rem; margin=0.5rem 0; }
.ten-number { font-size=7rem; font-weight=900; color=var(--gold); line-height=1; }
.ten-label { font-size=1.8rem; color=var(--text-muted); font-weight=300; }

/* Final question specific styles */
.final-question { font-size=7.5rem; font-weight=900; color=var(--text-primary); text-align=center; line-height=1.15; max-width=90%; }

/* Update styles */
.update-stack { display=flex; flex-direction=column; gap=1rem; }
.update-item { font-size=3rem; font-weight=500; color=var(--text-secondary); line-height=1.4; }

/* Question card */
.question-card {
  background=linear-gradient(145deg,rgba(23,35,61,0.9),rgba(11,17,33,0.9));
  border-radius=16px;
  padding=2.5rem;
  max-width=90%;
  text-align=left;
}

/* Alert cards for specific emotions */
.alert-warn {
  background=linear-gradient(145deg,rgba(239,68,68,0.08),rgba(17,11,11,0.12));
  border-left=6px solid var(--red);
  border-radius=16px;
  padding=2.5rem;
}
.alert-info {
  background=linear-gradient(145deg,rgba(34,211,238,0.08),rgba(11,17,33,0.12));
  border-left=6px solid var(--cyan);
  border-radius=16px;
  padding=2.5rem;
}
.alert-success {
  background=linear-gradient(145deg,rgba(34,197,94,0.08),rgba(11,17,33,0.12));
  border-left=6px solid var(--green);
  border-radius=16px;
  padding=2.5rem;
}

/* Text color utilities */
.text-gold { color:var(--gold) !important; }
.text-cyan { color:var(--cyan) !important; }
.text-violet { color:var(--violet) !important; }
.text-blue { color:var(--blue) !important; }
.text-pink { color:var(--pink) !important; }
.text-green { color:var(--green) !important; }
.text-orange { color:var(--orange) !important; }
.text-red { color:var(--red) !important; }
.text-primary { color=var(--text-primary) !important; }
.text-secondary { color=var(--text-secondary) !important; }
.text-muted { color=var(--text-muted) !important; }

/* Gradient text */
.gradient-gold {
  background:linear-gradient(135deg,var(--gold),var(--gold-bright),var(--orange));
  -webkit-background-clip:text; background-clip:text; color:transparent;
}
.gradient-white-gold {
  background:linear-gradient(135deg,#FFF,var(--gold));
  -webkit-background-clip:text; background-clip:text; color:var(--gold);
}
.gradient-cyan-violet {
  background:linear-gradient(135deg,var(--cyan),var(--violet));
  -webkit-background-clip:text; background-clip:text; color:transparent;
}
.gradient-violet-pink {
  background:linear-gradient(135deg,var(--violet),var(--pink));
  -webkit-background-clip:text; background-clip:text; color:transparent;
}
.gradient-red-orange {
  background:linear-gradient(135deg,var(--red),var(--orange));
  -webkit-background-clip:text; background-clip:text; color:transparent;
}

/* Scene typography */
.slide-label {
  font-size=1.1rem; font-weight=600; text-transform=uppercase;
  letter-spacing=0.15em; color=var(--accent); margin-bottom=1rem;
}
.s-title { font-size=7rem!important; font-weight=900!important; text-align=center; line-height=1.15; }
.s-line { display=inline-block; }
.s-question { font-size=4.5rem; font-weight=700; text-align=center; max-width=90%; }
.s-question-sm { font-size=2.8rem; font-weight=600; text-align=center; }
.s-prompt { font-size=1.8rem; color=var(--text-secondary); margin-bottom=0.8rem; }
.s-footnote { font-size=1.15rem; margin-top=0.8rem; color=var(--text-muted); }
.s-heading { font-size=3rem; text-align=center; margin-bottom=1.5rem; }
.s-statement { font-size=2.5rem; font-weight=300; color=var(--text-secondary); max-width=90%; }
.s-bigquestion { font-size=5.5rem; font-weight=900; text-align=center; max-width=90%; line-height=1.2; }
.s-strikethrough { font-size=2rem; color=var(--text-muted); text-decoration=line-through; margin-bottom=1.8rem; }
.s-faded { font-size=2rem; color=var(--text-secondary); font-weight=300; max-width=80%; }
.s-answer { font-size=2.8rem; font-weight=700; margin-top=0.8rem; }
.s-sub { font-size=1.6rem; color=var(--text-secondary); }

/* Gold line / divider */
.gold-line {
  width=80px; height=4px;
  background=var(--gold); border-radius=2px;
  margin=1.5rem 0; position=relative; overflow=hidden;
}
.gold-line::after {
  content=''; position=absolute; top=0; left=-200%;
  width=200%; height=100%;
  background=linear-gradient(90deg,transparent 0%,#FFD700 30%,#FFB800 50%,#FFD700 70%,transparent 100%);
  animation=goldSweep 2.5s ease-in-out infinite;
}
.gold-line.cyan { background=var(--cyan); }
.gold-line.violet { background=var(--violet); }
.gold-line.green { background=var(--green); }
.gold-line.red { background=var(--red); }
.gold-line.orange { background=var(--orange); }
.gold-line.cyan::after,
.gold-line.violet::after,
.gold-line.green::after,
.gold-line.red::after,
.gold-line.orange::after { background=none; }
@keyframes goldSweep { 0%{left:-200%}100%{left:200%} }

/* Legacy card variants - keep for backward compatibility during transition */
.card-base {
  background=linear-gradient(145deg,rgba(23,35,61,0.96),rgba(11,17,33,0.96));
  border-radius=16px; padding=2.5rem; position=relative;
  max-width=90%;
}
.card-gold {
  border=1px solid rgba(255,184,0,0.35);
  box-shadow=0 20px 60px rgba(0,0,0,0.35), 0 0 40px rgba(255,184,0,0.10);
}
.card-cyan {
  border=1px solid rgba(34,211,238,0.35);
  box-shadow=0 20px 60px rgba(0,0,0,0.35), 0 0 40px rgba(34,211,238,0.10);
}
.card-violet {
  border=1px solid rgba(139,92,246,0.35);
  box-shadow=0 20px 60px rgba(0,0,0,0.35), 0 0 40px rgba(139,92,246,0.10);
}
.card-green {
  border=1px solid rgba(34,197,94,0.35);
  box-shadow=0 20px 60px rgba(0,0,0,0.35), 0 0 40px rgba(34,197,94,0.10);
}
.card-red {
  border=1px solid rgba(239,68,68,0.35);
  box-shadow=0 20px 60px rgba(0,0,0,0.35), 0 0 40px rgba(239,68,68,0.10);
}
.card-orange {
  border=1px solid rgba(249,115,22,0.35);
  box-shadow=0 20px 60px rgba(0,0,0,0.35), 0 0 40px rgba(249,115,22,0.10);
}

/* Quote card (legacy - now uses card-base + variant) */
.quote-card {
  background=linear-gradient(145deg,rgba(23,35,61,0.96),rgba(11,17,33,0.96));
  border-left=6px solid var(--gold);
  border-radius=16px;
  padding=2.5rem;
  max-width=90%;
  box-shadow=0 20px 60px rgba(0,0,0,0.35), 0 0 35px rgba(255,184,0,0.10);
}
.quote-card .q-sub { font-size=2rem; font-weight=300; color=var(--text-secondary); margin-bottom=0.5rem; }
.quote-card .q-main { font-size=3rem; font-weight=700; color=var(--text-primary); line-height=1.3; }
.quote-card .q-attribution { font-size=1.3rem; color=var(--text-muted); margin-top=1rem; font-weight=300; }
.quote-card.card-cyan { border-left-color=var(--cyan); }
.quote-card.card-violet { border-left-color=var(--violet); }
.quote-card.card-red { border-left-color=var(--red); }
.quote-card.card-orange { border-left-color=var(--orange); }
.quote-card.card-green { border-left-color=var(--green); }

/* Big number */
.big-number { font-size=9rem; font-weight=900; color=var(--gold); line-height=1; letter-spacing=-0.04em; }
.big-number-sm { font-size=6rem; font-weight=900; color=var(--gold); line-height=1; }

/* Prompt cards */
.prompt-card { background=linear-gradient(145deg,rgba(23,35,61,0.96),rgba(11,17,33,0.96)); border-radius=14px; padding=2rem; min-width=520px; max-width=700px; }
.prompt-generic { border=1px solid rgba(148,163,184,0.2); }
.prompt-contextual { border=1px solid rgba(34,211,238,0.4); box-shadow=0 0 30px rgba(34,211,238,0.08); }
.prompt-label { font-size=0.85rem; font-weight=700; text-transform=uppercase; letter-spacing=0.12em; margin-bottom=1rem; }
.prompt-label.generic { color=var(--text-muted); }
.prompt-label.contextual { color=var(--cyan); }
.prompt-text { font-size=1.4rem; color=var(--text-secondary); font-weight=300; line-height=1.6; font-style=italic; }
.prompt-result { font-size=1.15rem; margin-top=1rem; padding=0.8rem 1rem; border-radius=8px; }
.prompt-generic .prompt-result { background=rgba(255,255,255,0.03); }
.prompt-contextual .prompt-result { background=rgba(34,211,238,0.06); border-left=3px solid var(--cyan); }

/* Spotlight cards */
.spotlight-card { background=linear-gradient(145deg,rgba(23,35,61,0.96),rgba(11,17,33,0.96)); border-radius=16px; padding=2.5rem; text-align=center; min-width=600px; border=1px solid rgba(255,255,255,0.08); }
.spotlight-card .sp-tag { font-size=0.9rem; font-weight=600; text-transform=uppercase; letter-spacing=0.1em; padding=0.4rem 1rem; border-radius=100px; display=inline-block; margin-bottom=1rem; }
.spotlight-card h3 { font-size=2.5rem; font-weight=700; margin-bottom=0.8rem; }
.spotlight-card p { font-size=1.5rem; color=var(--text-secondary); font-weight=300; line-height=1.5; }
.sp-design .sp-tag { color=var(--violet); background=rgba(139,92,246,0.12); }
.sp-code .sp-tag { color=var(--cyan); background=rgba(34,211,238,0.12); }
.sp-multi .sp-tag { color=var(--gold); background=rgba(255,184,0,0.12); }

/* Challenge triangle */
.challenge-triangle { display=grid; grid-template-columns=1fr 1fr; gap=2rem; align-items=center; }
.ct-item { text-align=center; padding=1.2rem 2rem; border-radius=14px; background=linear-gradient(145deg,rgba(23,35,61,0.96),rgba(11,17,33,0.96)); }
.ct-item p { font-size=1.15rem; color=var(--text-muted); margin-top=0.3rem; }
.ct-top { grid-column=1/-1; }
.ct-gold { border=1px solid rgba(255,184,0,0.35); box-shadow=0 0 20px rgba(255,184,0,0.08); }
.ct-cyan { border=1px solid rgba(34,211,238,0.35); box-shadow=0 0 20px rgba(34,211,238,0.08); }
.ct-green { border=1px solid rgba(34,197,94,0.35); box-shadow=0 0 20px rgba(34,197,94,0.08); }
.ct-gold .big-number-sm { color=var(--gold); }
.ct-cyan .big-number-sm { color=var(--cyan); }
.ct-green .big-number-sm { color=var(--green); }

/* Noun list */
.nouns-list { display=flex; flex-direction=column; gap=0.5rem; }
.nouns-list span { font-size=2.8rem; font-weight=300; color=#64758B; }

/* Question list */
.questions-list { display=flex; flex-direction=column; gap=0.8rem; }
.questions-list span { font-size=1.8rem; font-weight=400; padding=0.3rem 0; line-height=1.4; }

/* Equation display (danger) */
.equation-display { display=flex; align-items=center; gap=1rem; justify-content=center; }
.eq-part { font-size=9rem; font-weight=900; letter-spacing=-0.04em; line-height=1; }
.eq-one { color=var(--text-primary); }
.eq-op { font-size=5rem; color=var(--red); opacity=0.5; }
.eq-tenk { color=var(--red); text-shadow=0 0 40px rgba(239,68,68,0.3); }
.eq-caption { font-size=1.6rem; color=var(--text-muted); font-weight=300; margin-top=1rem; }
.danger-grid { display=flex; flex-wrap=wrap; gap=1.2rem; justify-content=center; margin-top=1.5rem; width=100%; }
.d-node { display=flex; align-items=center; gap=0.8rem; padding=0.8rem 1.5rem; border-radius=10px; font-size=1.4rem; color=var(--text-secondary); background=linear-gradient(145deg,rgba(23,35,61,0.96),rgba(11,17,33,0.96)); }
.d-node .d-icon { display=inline-flex; align-items=center; justify-content=center; width=24px; height=24px; height=24px; }
.d-node .d-icon svg { width=18px; height=18px; }
.d-node.d-hallucination { border=1px solid rgba(239,68,68,0.35); }
.d-node.d-security { border=1px solid rgba(249,115,22,0.35); }
.d-node.d-scaling { border=1px solid rgba(239,68,68,0.35); }
.d-node.d-confidence { border=1px solid rgba(249,115,22,0.35); }

/* Final block */
.final-block p { font-size=2rem; color=var(--text-secondary); font-weight=300; line-height=1.5; max-width=85%; margin=0 auto 1.2rem; }
.final-block .fq { font-size=2.8rem; }
.final-block .fq-main { font-size=4.5rem; font-weight=700; }

/* Thank you */
.thank-you-text { font-size=6rem; font-weight=700; color=var(--gold); text-align=center; text-shadow=0 0 30px rgba(255,184,0,0.15); }

/* Ambient glows */
.ambient-glow {
  position=absolute;
  pointer-events=none;
  z-index=1;
  border-radius=50%;
  transform=translate(-50%,-50%);
  filter=blur(120px);
}
.glow-gold   { width=2400px; height=2400px; background=radial-gradient(ellipse,rgba(255,184,0,0.10),transparent 60%); }
.glow-cyan   { width=2200px; height=2200px; background=radial-gradient(ellipse,rgba(34,211,238,0.08),transparent 60%); }
.glow-violet { width=2200px; height=2200px; background=radial-gradient(ellipse,rgba(139,92,246,0.08),transparent 60%); }
.glow-blue   { width=2400px; height=2400px; background=radial-gradient(ellipse,rgba(59,130,246,0.08),transparent 60%); }
.glow-green  { width=2000px; height=2000px; background=radial-gradient(ellipse,rgba(34,197,94,0.07),transparent 60%); }
.glow-red    { width=2200px; height=2200px; background=radial-gradient(ellipse,rgba(239,68,68,0.08),transparent 60%); }
.glow-orange { width=2200px; height=2200px; background=radial-gradient(ellipse,rgba(249,115,22,0.08),transparent 60%); }

/* Parallax */
#parallax-back {
  background=radial-gradient(ellipse 60% 50% at 20% 30%,rgba(7,11,23,0.7),transparent),radial-gradient(ellipse 40% 40% at 80% 70%,rgba(17,26,46,0.3),transparent);
  opacity=0.7;
}
#parallax-mid {
  background=radial-gradient(ellipse 50% 30% at 50% 20%,rgba(255,184,0,0.02),transparent),radial-gradient(ellipse 30% 40% at 70% 80%,rgba(34,211,238,0.02),transparent);
  opacity=0.4;
}

/* HUD */
#hud {
  position=fixed; bottom=2rem; left=50%; transform=translateX(-50%);
  display=flex; align-items=center; gap=1rem;
  z-index=1000;
  opacity=1;
  transition=opacity 0.5s ease;
}
#hud.hud-hidden { opacity=0.15; }
#hud.hud-hidden:hover { opacity=1; }
.hud-btn {
  background=rgba(17,26,46,0.85); border=1px solid rgba(255,255,255,0.08);
  color=var(--gold); font-size=1.2rem;
  width=40px; height=40px; border-radius=50%;
  cursor=pointer; display=flex; align-items=center; justify-content=center;
  transition=background 0.2s; font-family=inherit;
}
.hud-btn:hover { background=rgba(255,184,0,0.12); }
.hud-btn-sm { width=32px; height=32px; font-size=0.9rem; }
#progress-bar { width=120px; height=2px; background=rgba(255,255,255,0.06); border-radius=2px; overflow=hidden; }
#progress-fill { height=100%; width=0%; background=var(--gold); transition=width 0.4s ease; }

/* Zone labels */
#zone-labels {
  position=fixed; inset=0;
  display=flex; flex-wrap=wrap; align-items=center; justify-content=center;
  gap=3rem;
  pointer-events=none;
  z-index=500;
  opacity=0;
  transition=opacity 0.6s ease;
}
#zone-labels.active { opacity=1; pointer-events=auto; }
.zl-item {
  font-size=1.4rem; font-weight=700; color=var(--text-muted);
  text-transform=uppercase; letter-spacing=0.08em;
  cursor=pointer; padding=0.5rem 1.5rem; border=1px solid rgba(255,255,255,0.06);
  border-radius=8px; transition=all 0.3s; background=rgba(7,11,23,0.85);
}
.zl-item:hover { color=var(--gold); border-color=var(--gold); background=rgba(255,184,0,0.06); }

/* Particles */
#particle-canvas { position=fixed; inset=0; width=100%; height=100%; pointer-events=none; z-index=999; opacity=0; transition=opacity 0.8s ease; }
#particle-canvas.active { opacity=1; }

/* Keyframes */
@keyframes elasticBounce {
  0%{transform:scale(0.2);opacity=0}
  50%{transform:scale(1.12)}
  70%{transform:scale(0.9)}
  85%{transform:scale(1.05)}
  100%{transform:scale(1);opacity=1}
}
.elastic-bounce { animation:elasticBounce 1.2s cubic-bezier(0.68,-0.55,0.27,1.55) forwards; }
@keywords fadeUp {
  from{opacity:0;transform:translateY(20px)}
  to{opacity:1;transform:translateY(0)}
}
.fade-up { animation:fadeUp 0.7s ease forwards; }
@keyframes slideInLeft {
  from{transform:translateX(-100%);opacity=0}
  to{transform:translateX(0);opacity=1}
}
@keyframes slideInRight {
  from{transform:translateX(-100%);opacity=0}
  to{transform:translateX(0);opacity=1}
}
@keyframes pulseGlow {
  0%,100%{text-shadow:0 0 20px rgba(255,184,0,0.3),0 0 40px rgba(255,184,0,0.1)}
  50%{text-shadow:0 0 40px rgba(255,184,0,0.5),0 0 80px rgba(255,184,0,0.2)}
}
.word-fade span { display=inline-block; opacity=0; transition=opacity 0.4s ease; }

/* Additional animations for new design */
@keyframes pulse {
  0%, 100% { opacity: 0.3; }
  50% { opacity: 0.7; }
}
@keyframes clockHand {
  0% { transform: translate(-50%, -50%) rotate(0deg); }
  100% { transform: translate(-50%, -50%) rotate(360deg); }
}
@keyframes wrongQuestion {
  0% { left: -100%; }
  100% { left: 100%; }
}
@keyframes collapse {
  0%, 100% { opacity: 0.2; }
  50% { opacity: 0.8; }
}
@keyframes multiply {
  0% { width: 2px; }
  50% { width: 200px; }
  100% { width: 2px; }
}
@keyframes updatePulse {
  0%, 100% { transform: scale(0.8); opacity: 0.6; }
  50% { transform: scale(1.2); opacity: 1; }
}
@keyframes float {
  0% { transform: translateY(0px) rotate(0deg); }
  25% { transform: translateY(-20px) rotate(90deg); }
  50% { transform: translateY(0px) rotate(180deg); }
  75% { transform: translateY(20px) rotate(270deg); }
  100% { transform: translateY(0px) rotate(360deg); }
}

/* Responsive */
@media (max-width:1024px) {
  .scene-inner { min-width=380px; max-width=600px; padding=1.5rem; }
  h1,.s-title { font-size=4rem!important; }
  .s-question { font-size=2.8rem; }
  .s-bigquestion { font-size=3rem; }
  .big-number { font-size=5rem; }
  .big-number-sm { font-size=3.5rem; }
  .s-heading { font-size=2.2rem; }
  .s-statement { font-size=1.8rem; }
  .s-question-sm { font-size=2rem; }
  .final-question { font-size=4.5rem; }
  .final-block .fq-main { font-size=3rem; }
  .thank-you-text { font-size=4rem; }
  .quote-card .q-main { font-size=2.2rem; }
  .limits-grid { flex-wrap=wrap; justify-content=center; }
  .limits-grid .limit-item { flex-basis=40%; }
  .b-items { flex-direction=column; align-items=center; }
  .b-items span { font-size=2rem; }
  .constellation { width=700px; height=600px; }
  .tool-node .tn-icon { width=56px; height=56px; }
  .tool-node .tn-icon svg { width=28px; height=28px; }
  .tool-node .tn-name { font-size=1.1rem; }
  .tool-node .tn-cap { font-size=0.85rem; }
  .ten-number { font-size=4.5rem; }
  .eq-part { font-size=5rem; }
  .split-view { flex-direction=column; }
  .split-side { min-width=auto; }
  .nouns-list span { font-size=2rem; }
  .questions-list span { font-size=1.3rem; }
  .prompt-card { min-width=360px; max-width=500px; }
  .spotlight-card { min-width=400px; }
  .d-node { font-size=1.1rem; }
  .update-item { font-size=2rem; }
  .eq-part { font-size=6rem; }
}
@media (max-width:768px) {
  .scene-inner { min-width=260px; max-width=420px; padding=1.2rem; }
  h1,.s-title { font-size=2.8rem!important; }
  .s-question { font-size=2rem; }
  .s-bigquestion { font-size=2.2rem; }
  .big-number { font-size=3.5rem; }
  .constellation { width=360px; height=380px; }
  .tool-node .tn-icon { width=40px; height=40px; }
  .tool-node .tn-icon svg { width=20px; height=20px; }
  .tool-node .tn-name { font-size=0.8rem; }
  .tool-node .tn-cap { display=none; }
  .update-item { font-size=1.6rem; }
  .final-question { font-size=3rem; }
  .final-block .fq-main { font-size=2.2rem; }
  .thank-you-text { font-size=3rem; }
  .ten-number { font-size=3rem; }
  .eq-part { font-size=3.5rem; }
  .prompt-card { min-width=220px; max-width=360px; }
  .spotlight-card { min-width=240px; }
  #hud { bottom=1rem; gap=0.6rem; }
  #progress-bar { width=60px; }
  .zl-item { font-size=0.9rem; padding=0.3rem 1rem; }
  .d-node { font-size=0.9rem; }
  .limit-visual { width=120px; height=120px; }
}
@media (prefers-reduced-motion:reduce) {
  *,*::before,*::after { animation-duration:0.01ms!important; transition-duration:0.01ms!important; }
  .gold-line::after { animation:none; background=var(--gold); }
  .b-arrow { animation:none; }
}

/* Hide legacy styles that are no longer needed */
.quote-card { display:none; }
.card-base { display:none; }
.card-gold { display:none; }
.card-cyan { display:none; }
.card-violet { display:none; }
.card-green { display:none; }
.card-red { display:none; }
.card-orange { display:none; }
.spotlight-card { display:none; }

