/* ===== SCENE CONTENT BOUNDS MEASUREMENT ===== */
function getSceneContentBounds(el) {
  var inner = el.querySelector('.scene-inner');
  if (!inner) return {width:600, height:400};

  var elements = [];

  // Scoped: AI ecosystem — measure semantic content only, not constellation border box
  if (el.id === 'scene-ai-ecosystem') {
    var centerEl = el.querySelector('.constellation-center');
    if (centerEl) elements.push(centerEl);
    var toolNodes = el.querySelectorAll('.tool-node');
    toolNodes.forEach(function(n) { elements.push(n); });
  } else {
    // 1. Direct children of .scene-inner (main content blocks)
    var children = inner.children;
    for (var i = 0; i < children.length; i++) {
      elements.push(children[i]);
    }

    // 2. Absolutely positioned .tool-node descendants that may overflow their parent
    var toolNodes = inner.querySelectorAll('.tool-node');
    for (var i = 0; i < toolNodes.length; i++) {
      if (elements.indexOf(toolNodes[i]) === -1) {
        elements.push(toolNodes[i]);
      }
    }
  }

  // 3. Temporarily neutralize GSAP entrance transforms on measured elements
  //    (scale affects getBoundingClientRect dimensions; translate/opacity do not)
  var scaleSaves = [];
  for (var i = 0; i < elements.length; i++) {
    var e = elements[i];
    var s = gsap.getProperty(e, 'scale');
    if (s !== undefined && Math.abs(s - 1) > 0.01) {
      scaleSaves.push({el:e, scale:s});
      gsap.set(e, {scale:1, overwrite:'auto'});
    }
  }

  // 4. Compute union bounding rect
  var minLeft = Infinity, minTop = Infinity;
  var maxRight = -Infinity, maxBottom = -Infinity;

  for (var i = 0; i < elements.length; i++) {
    var child = elements[i];
    var cs = getComputedStyle(child);
    if (cs.display === 'none') continue;
    var rect = child.getBoundingClientRect();
    if (rect.width === 0 && rect.height === 0) continue;
    minLeft = Math.min(minLeft, rect.left);
    minTop = Math.min(minTop, rect.top);
    maxRight = Math.max(maxRight, rect.right);
    maxBottom = Math.max(maxBottom, rect.bottom);
  }

  // 5. Restore GSAP entrance transforms
  for (var i = 0; i < scaleSaves.length; i++) {
    gsap.set(scaleSaves[i].el, {scale:scaleSaves[i].scale, overwrite:'auto'});
  }

  if (minLeft === Infinity) {
    return {width:inner.scrollWidth||600, height:inner.scrollHeight||400};
  }

  // Correct for camera transform (getBoundingClientRect includes camera zoom/translate)
  var currentZoom = camera.z || 1;
  var visualW = (maxRight - minLeft) / currentZoom;
  var visualH = (maxBottom - minTop) / currentZoom;

  return {width:visualW, height:visualH};
}

/* ===== SAFE-FIT ZOOM ===== */
function calculateSafeFitZoom(contentW, contentH, preferredZ) {
  var safeW = window.innerWidth * 0.88;
  var safeH = window.innerHeight * 0.80;
  var fitX = safeW / contentW;
  var fitY = safeH / contentH;
  var safeZ = Math.min(fitX, fitY);
  safeZ = Math.max(0.15, Math.min(2.5, safeZ));
  return Math.min(preferredZ, safeZ);
}

/* ===== FORCE FINAL SCENE STATE (for audit) ===== */
function forceSceneFinalState(index) {
  var el = document.getElementById('scene-' + scenes[index].id);
  if (!el) return;
  gsap.set(el.querySelectorAll('.s-line'),          {y:0,opacity:1});
  gsap.set(el.querySelector('.s-sub'),              {opacity:1});
  gsap.set(el.querySelectorAll('.s-question'),       {scale:1,opacity:1});
  gsap.set(el.querySelectorAll('.quote-card'),       {y:0,scale:1,opacity:1});
  gsap.set(el.querySelectorAll('.limit-item'),       {scale:1,opacity:1});
  gsap.set(el.querySelector('.b-old'),               {opacity:0.5});
  gsap.set(el.querySelectorAll('.b-items span'),     {x:0,opacity:1});
  gsap.set(el.querySelectorAll('.s-statement'),      {y:0,opacity:1});
  gsap.set(el.querySelector('.split-worried'),       {x:0,opacity:1});
  gsap.set(el.querySelector('.split-over'),          {x:0,opacity:1});
  gsap.set(el.querySelector('.s-bigquestion'),       {scale:1,opacity:1});
  gsap.set(el.querySelectorAll('.big-number'),       {scale:1,opacity:1});
  gsap.set(el.querySelectorAll('.ct-item'),          {scale:1,opacity:1});
  gsap.set(el.querySelector('.s-question-sm'),       {opacity:1});
  gsap.set(el.querySelectorAll('.nouns-list span'),  {x:0,opacity:1});
  gsap.set(el.querySelectorAll('.questions-list span'), {x:0,opacity:1});
  gsap.set(el.querySelectorAll('.tool-node'),        {scale:1,opacity:1});
  gsap.set(el.querySelector('.constellation-center'), {scale:1,opacity:1});
  gsap.set(el.querySelectorAll('.ten-number'),       {scale:1,opacity:1});
  gsap.set(el.querySelectorAll('.eq-part'),          {scale:1,opacity:1});
  gsap.set(el.querySelectorAll('.d-node'),           {y:0,opacity:1});
  gsap.set(el.querySelectorAll('.update-item'),      {y:0,opacity:1});
  gsap.set(el.querySelectorAll('.fq > *'),           {y:0,opacity:1});
  gsap.set(el.querySelector('.fq-main'),             {scale:1,textShadow:'0 0 30px rgba(255,184,0,0.2)'});
  gsap.set(el.querySelector('.thank-you-text'),     {scale:1,opacity:1});
  gsap.set(el.querySelectorAll(':scope > .scene-inner > *'), {y:0,opacity:1});
  if (index === 18) {
    var target = document.getElementById('typewriter-target');
    if (target) target.textContent = 'I am a college student in Karnataka with ₹5,000 and 7 days. Before suggesting, ask me questions one by one. Challenge my assumptions.';
  }
  if (index === 31) {
    var fq = document.getElementById('final-question-text');
    if (fq) {
      // Ensure any word-fade spans are visible
      var wfSpans = fq.querySelectorAll('[data-wf="1"]');
      for (var si = 0; si < wfSpans.length; si++) { wfSpans[si].style.opacity = '1'; }
    }
  }
  if (index === 21 && !connDrawn) { drawConnections(); if(connDrawn) connDrawn = true; }
}

