function isImpactScene(i) { return impactScenes.indexOf(i) >= 0; }

/* ===== CAMERA ENGINE ===== */
function applyCameraTransform() {
  var vw = window.innerWidth;
  var vh = window.innerHeight;
  world.style.transform = 'translate3d('+(vw/2)+'px,'+(vh/2)+'px,0) scale('+camera.z+') rotate('+(camera.r||0)+'deg) translate3d('+(-camera.x)+'px,'+(-camera.y)+'px,0)';
  var pOffX = (camera.x) * 0.08;
  var pOffY = (camera.y) * 0.08;
  parallaxBack.style.transform = 'translate3d('+(-pOffX)+'px,'+(-pOffY)+'px,0)';
  var mOffX = (camera.x) * 0.25;
  var mOffY = (camera.y) * 0.25;
  parallaxMid.style.transform = 'translate3d('+(-mOffX)+'px,'+(-mOffY)+'px,0)';
}

/* ===== ECOSYSTEM CAMERA TARGET ===== */
function getSceneCameraTarget(index) {
  var s = scenes[index];
  if (index !== 21) return { x: s.x, y: s.y };
  var el = document.getElementById('scene-' + s.id);
  if (!el) return { x: s.x, y: s.y };
  var elements = [];
  var center = el.querySelector('.constellation-center');
  if (center) elements.push(center);
  var nodes = el.querySelectorAll('.tool-node');
  nodes.forEach(function(n) { elements.push(n); });
  var minL = Infinity, minT = Infinity, maxR = -Infinity, maxB = -Infinity;
  for (var i = 0; i < elements.length; i++) {
    var r = elements[i].getBoundingClientRect();
    if (r.width === 0 && r.height === 0) continue;
    minL = Math.min(minL, r.left); minT = Math.min(minT, r.top);
    maxR = Math.max(maxR, r.right); maxB = Math.max(maxB, r.bottom);
  }
  if (minL === Infinity) return { x: s.x, y: s.y };
  var cCX = (minL + maxR) / 2, cCY = (minT + maxB) / 2;
  var vw = window.innerWidth, vh = window.innerHeight;
  return {
    x: (cCX - vw / 2) / camera.z + camera.x,
    y: (cCY - vh / 2) / camera.z + camera.y
  };
}

/* ===== SCENE STATE MANAGEMENT ===== */
function setActiveScene(index) {
  document.querySelectorAll('.scene').forEach(function(el) {
    el.classList.remove('is-active', 'is-entering', 'is-leaving');
    el.style.opacity = '';
  });
  var el = document.getElementById('scene-' + scenes[index].id);
  if (el) el.classList.add('is-active');
}

function goToScene(index, playEntrance) {
  if (index < 0 || index >= scenes.length) return;
  if (overviewActive) { exitOverview(); }
  if (currentNavTimeline) { currentNavTimeline.kill(); currentNavTimeline = null; }

  var fromIndex = currentScene;
  var fromEl = document.getElementById('scene-' + scenes[fromIndex].id);
  var targetEl = document.getElementById('scene-' + scenes[index].id);
  if (!fromEl || !targetEl) return;
  var navId = ++navVersion;

  // Clean stale states
  document.querySelectorAll('.scene').forEach(function(el) {
    el.classList.remove('is-entering', 'is-leaving');
  });

  triggerSceneLeave(fromIndex);

  // Measure content BEFORE prepare (avoid GSAP entrance scale distorting rects)
  targetEl.classList.add('is-measuring');
  var bounds = getSceneContentBounds(targetEl);
  targetEl.classList.remove('is-measuring');

  // PREPARE target entrance state while still hidden
  prepareSceneForEnter(index);

  // Calculate safe zoom and camera target
  var s = scenes[index];
  var preferredZ = s.z;
  var finalZ = calculateSafeFitZoom(bounds.width, bounds.height, preferredZ);
  var camTarget = getSceneCameraTarget(index);

  var settled = false;
  var isEntrancePlayed = false;

  function entranceCallback() {
    if (navId !== navVersion) return;
    if (isEntrancePlayed) return;
    isEntrancePlayed = true;
    if (playEntrance !== false) { triggerSceneEnter(index); }
    else { forceSceneFinalState(index); }
  }

  function completeCallback() {
    if (navId !== navVersion) return;
    if (settled) return;
    settled = true;
    fromEl.classList.remove('is-leaving');
    targetEl.classList.remove('is-entering');
    setActiveScene(index);
    currentScene = index;
    currentNavTimeline = null;
    updateProgress();
  }

  if (playEntrance === false) {
    // Instant/final state -- used by audit
    gsap.killTweensOf(camera);
    camera.x = camTarget.x; camera.y = camTarget.y; camera.z = finalZ; camera.r = s.r || 0;
    applyCameraTransform();
    fromEl.classList.remove('is-leaving');
    targetEl.classList.remove('is-entering');
    setActiveScene(index);
    currentScene = index;
    forceSceneFinalState(index);
    updateProgress();
    return;
  }

  var dur = reduceMotion ? 0.001 : (s.d || 1.5);

  // Mark states
  fromEl.classList.add('is-leaving');
  targetEl.classList.add('is-entering');

  currentNavTimeline = gsap.timeline({onComplete: completeCallback});

  // Departure fade: from scene over first 30%
  if (!reduceMotion) {
    currentNavTimeline.to(fromEl, {opacity:0, duration:dur*0.30, ease:'power2.in'}, 0);
  } else {
    gsap.set(fromEl, {opacity:0});
  }

  // Camera movement: full duration
  currentNavTimeline.to(camera, {
    x: camTarget.x, y: camTarget.y, z: finalZ, r: s.r || 0,
    duration: dur, ease: 'power3.inOut',
    onUpdate: applyCameraTransform
  }, 0);

  // Entrance trigger
  var entranceTime = reduceMotion ? 0 : (isImpactScene(index) ? dur : dur * 0.80);
  currentNavTimeline.addLabel('sceneEnter', entranceTime);
  currentNavTimeline.call(entranceCallback, null, 'sceneEnter');
}

function nextScene() { goToScene(currentScene + 1); }
function prevScene() { goToScene(currentScene - 1); }
function firstScene() { goToScene(0); }
function lastScene() { goToScene(scenes.length - 1); }

function updateProgress() {
  if (progressFill) {
    progressFill.style.width = ((currentScene + 1) / scenes.length * 100) + '%';
  }
}

/* ===== SCENE LIFECYCLE ===== */
function triggerSceneEnter(index) {
  var scene = scenes[index];
  var el = document.getElementById('scene-' + scene.id);
  if (!el) return;

  var fnName = 'enter_' + scene.id.replace(/-/g,'_');
  if (typeof window[fnName] === 'function') {
    window[fnName](el);
  } else {
    var children = el.querySelectorAll(':scope > .scene-inner > *');
    gsap.to(children, {opacity:1,y:0,duration:0.5,stagger:0.03,ease:'power2.out',delay:0.1});
  }

  if (particleScenes.indexOf(index) >= 0) { startParticles(); }
  else { stopParticles(); }

  if (index === 18) { startTypewriter(); }

  if (index === 31) {
    var fq = document.getElementById('final-question-text');
    if (fq) { animateWordFade(fq, 350); }
  }

  if (index === 33) {
    var fqEl = document.querySelector('#scene-choose-questions .fq-main');
    if (fqEl) { gsap.fromTo(fqEl, {textShadow:'0 0 0px rgba(255,184,0,0)'}, {textShadow:'0 0 40px rgba(255,184,0,0.3)',duration:1.5,ease:'power2.out'}); }
  }
}

function triggerSceneLeave(index) {
  var scene = scenes[index];
  var el = document.getElementById('scene-' + scene.id);
  if (particleScenes.indexOf(index) >= 0) { stopParticles(); }
  if (index === 21 && connCtx) { connCtx.clearRect(0,0,connCanvas.width,connCanvas.height); connDrawn = false; }
}

