/* ===== RESIZE HANDLING ===== */
var resizeTimeout = null;
window.addEventListener('resize', function() {
  clearTimeout(resizeTimeout);
  resizeTimeout = setTimeout(function() {
    // Re-measure current scene and recalculate zoom
    var curEl = document.getElementById('scene-' + scenes[currentScene].id);
    if (curEl) {
      var bounds = getSceneContentBounds(curEl);
      var finalZ = calculateSafeFitZoom(bounds.width, bounds.height, scenes[currentScene].z);
      camera.z = finalZ;
    }
    applyCameraTransform();
    resizeParticleCanvas();
    // Recalculate camera target and redraw connections for ecosystem
    if (currentScene === 21) {
      var ecoTarget = getSceneCameraTarget(21);
      camera.x = ecoTarget.x;
      camera.y = ecoTarget.y;
      if (connCtx) { connCtx.clearRect(0, 0, connCanvas.width, connCanvas.height); }
      connDrawn = false;
      requestAnimationFrame(function() { drawConnections(); });
    }
  }, 100);
});

/* ===== VISIBILITY CHANGE ===== */
document.addEventListener('visibilitychange', function() {
  if (document.hidden) {
    if (pRaf) { cancelAnimationFrame(pRaf); pRaf = null; }
  } else {
    if (particleActive) {
      animateParticles();
    }
  }
});

