/* ===== SCENE FRAMING AUDIT ===== */
function auditSceneFraming() {
  var safeW = window.innerWidth * 0.88;
  var safeH = window.innerHeight * 0.80;
  var VW = window.innerWidth;
  var VH = window.innerHeight;
  var results = [];

  for (var i = 0; i < scenes.length; i++) {
    var s = scenes[i];
    // Navigate instantly without entrance
    goToScene(i, false);
    // Force final state
    forceSceneFinalState(i);
    // Measure
    var el = document.getElementById('scene-' + s.id);
    var inner = el ? el.querySelector('.scene-inner') : null;
    var cw = 0, ch = 0;
    if (inner) { cw = inner.scrollWidth || 0; ch = inner.scrollHeight || 0; }
    var renderedW = cw * camera.z;
    var renderedH = ch * camera.z;
    var leftClip = renderedW > safeW ? 1 : 0;
    var topClip = renderedH > safeH ? 1 : 0;
    var rightClip = leftClip;
    var bottomClip = topClip;
    var hudOverlap = (camera.y + (ch * camera.z)/2 + 20) > (VH - 60) ? 1 : 0;

    // Check inactive scene leaks
    var inactiveLeak = 0;
    document.querySelectorAll('.scene').forEach(function(other) {
      if (other === el) return;
      if (other.style.visibility === 'visible' || other.classList.contains('is-active') || other.classList.contains('is-entering')) {
        var rect = other.getBoundingClientRect();
        if (rect.right > 0 && rect.left < VW && rect.bottom > 0 && rect.top < VH) {
          inactiveLeak = 1;
        }
      }
    });

    var status = (leftClip + topClip + rightClip + bottomClip + hudOverlap + inactiveLeak === 0) ? 'PASS' : 'FAIL';
    results.push({
      index:i, scene:s.id, zoom:camera.z.toFixed(3),
      contentW:cw, contentH:ch,
      renderedW:Math.round(renderedW), renderedH:Math.round(renderedH),
      leftClip:leftClip, topClip:topClip, rightClip:rightClip, bottomClip:bottomClip,
      hudOverlap:hudOverlap, inactiveLeak:inactiveLeak,
      status:status
    });
  }
  console.table(results);
  var pass = results.filter(function(r){return r.status==='PASS';}).length;
  console.log('Audit: ' + pass + '/' + results.length + ' PASS');
  return results;
}

